window.QUICK = {"L01":{"sec":[{"h":"الوسطية والقدوة والحياد","pts":["**الوسطية** هي الاعتدال بين الغلو (الزيادة حتى التشدد) والتفريط (التقصير والتهاون). ويغرس المعلم الاعتدال والتسامح والتعايش بسلوكه قبل كلامه.","مشاركة المعلم في ندوة عن **التطرف الفكري** تزوّد طلابه بخبرات عن القضايا المجتمعية. وهي تخدم مؤشر المعيار 1.1 الذي يطلب أنشطة تعزز الوسطية والتسامح ونبذ التطرف.","المعلم **قدوة** لطلابه داخل المدرسة وخارجها، ولذلك تُعلَّم القيم بالمواقف العملية التي يرونها منه، لا بحصة وعظ. ورقيبه في ذلك بعد الله ضميره اليقظ.","إذا ورد «المعلم القدوة» في الأسئلة، فالمقصود **حسن التعامل** مع الطلاب؛ لأن قدوته تظهر في معاملته اليومية لهم.","**النمذجة** أن يُظهر المعلم القيمة بفعله أمام طلابه. مثال ذلك أن يُرفع الأذان أثناء الشرح فيتوقف المعلم ويردده معهم؛ أما تذكيرهم بواجب المسلم ثم إكمال الشرح فوعظ لفظي يخالفه الفعل.","في القضايا **الخلافية**، كالمسائل الفقهية المختلف فيها والشؤون السياسية، يلتزم المعلم **الحياد** ولا يفرض رأيه. ذلك أن مدونة 1447 تنص على تجنب الدخول في نقاشات حولها، فيحيل الطالب إلى المصادر والجهات المختصة.","أما **الثوابت** فلا حياد فيها، بل يعلّمها المعلم بوضوح؛ لأن الحياد خاص بالقضايا الخلافية.","**توضيح القيم** (راث وهارمن وسايمون) أسلوب يكتشف به الطالب قيمه بنفسه. ومن ثَمّ لا يلقّنه المعلم القيمة جاهزة، بل يدفعه إلى التفكير فيها.","من أساليب توضيح القيم **الاستجابة الموضحة**، وهي سؤال قصير يرد به المعلم على عبارة الطالب دون وعظ أو حكم. مثال ذلك: «هل ترضى أن يعاملك الآخرون كذلك؟».","**المحاكمة العقلية** أن تُعرض قضية قيمية فيوازن الطلاب أدلة الطرفين حتى يصلوا إلى **حكم مسبَّب**. وتناسب المرحلة الثانوية؛ لأن طلابها قادرون على التفكير المجرد."]},{"h":"الحوار والهوية الوطنية","pts":["الطالب الجدلي الذي يشكك في الثوابت يُحاوَر بـ**الأدلة المنطقية والقدوة العملية**: إنصات، ثم توضيح، ثم شواهد تناسب عمره. أما إغلاق باب الحوار فقمع، وأما إحالته إلى موقع إلكتروني فتنصّل.","حب الوطن لا يتعارض مع الانتماء إلى الأمة، وهذا ما يبيّنه المعلم بحوار هادئ إذا سأله طالب: «أيهما أهم: الأمة أم الوطن؟». ومن ثَمّ يُستبعد كل بديل يُسكت الطالب أو يسخر منه.","تبدأ تنمية الهوية الوطنية بـ**غرس المفهوم**، أي مفهوم حب الوطن والمواطنة. ثم يُدعم المفهوم بشواهد يراها الطالب، وبعد ذلك تنتقل القيمة من الإصغاء إلى السلوك.","تُعزَّز الهوية الوطنية بـ**الشواهد والإحصاءات والمنجزات** المرتبطة بالدرس، لا بالوعظ؛ فعرض جهود المملكة في خدمة الحرمين والحجاج مثلاً ينمّي المواطنة الصالحة.","الأعلام المعلّقة والبرامج الثقافية **وسائل تابعة** لا غايات؛ لأنها تخدم المفهوم بعد غرسه ولا تغني عنه.","المواطنة قيمة وجدانية تتدرج في سلّم **كراثول**: الاستقبال، ثم الاستجابة، ثم التقدير، ثم التنظيم، ثم **تمثّل القيمة**. وهو أعلى مستوياته، وفيه تصير المواطنة سلوكاً تلقائياً، كأن يكون الطالب قدوة لأسرته.","في ترتيب أهداف المواطنة من الأدنى، يأتي إبداء الاهتمام بحديث المعلم (استقبال) قبل المشاركة في ندوة (استجابة). فالبديل الذي يبدأ بالمشاركة خاطئ؛ لأنه يتجاوز الاستقبال."],"m":[1]},{"h":"التراث والمناسبات","pts":["ينص مؤشر الممارس في المعيار 1.2 على أن **يوظف المعلم** خبرات ومواقف وأنشطة تعليمية تدعم الاعتزاز بالهوية الوطنية والتراث. ومعنى ذلك أن يدخل التراث في الدرس نفسه، لا أن يبقى مناسبة عابرة.","أقوى نشاط لتعزيز الاعتزاز بالتراث خبرة يعيشها الطالب، لا صورة تُعلَّق ولا محاضرة ولا مطوية. ففي درس عن البيئة المحلية تقابل الطالبات كبار السن لتوثيق حرفة تقليدية، ثم يعرضنها على زميلاتهن.","التراث نوعان: أولهما **التراث المادي**، وهو ما يُرى ويُلمس، كالمباني التاريخية والآثار والأدوات والأزياء والقطع الحرفية.","أما **التراث غير المادي** فهو الموروث غير الملموس، كالعادات وآداب الضيافة والأمثال والشعر والعرضة، ومهارات الحِرف التقليدية كالسدو. وعليه تُعدّ القطعة الحرفية تراثاً مادياً، في حين تُعدّ مهارة صنعها تراثاً غير مادي.","**تحويل المباني التراثية إلى حديثة** لا يصلح نشاطاً لتعزيز التراث؛ لأنه يناقض قيمة الحفاظ عليه. لكنّ الترميم الذي يحفظ الطابع الأصلي يعزز هذه القيمة، ومثله الفيلم الوثائقي والمطويات التوعوية.","المناسبات الوطنية ثلاث: يوم التأسيس (22 فبراير) لذكرى تأسيس الدولة السعودية الأولى، واليوم الوطني (23 سبتمبر) لذكرى التوحيد، ويوم العلم (11 مارس).","تَعُدّ قواعد السلوك والمواظبة 1447 المشاركة الإيجابية في المناسبات الوطنية من **السلوك المتميز** (الانتماء الوطني). فالمطلوب الاحتفاء بها بأنشطة هادفة، لا بالمظاهر.","تنوع تراث المناطق ولهجاتها **ثراء لهوية وطنية واحدة**، والتعريف به يعزز الوحدة الوطنية. ولذلك إذا سخر طلاب من لهجة زميلهم، وظّف المعلم الموقف لبيان هذا الثراء بشواهد، لا بعقاب علني ولا بتجاهل."],"m":[2]},{"h":"التنوع الثقافي","pts":["**التنوع الثقافي** وجود خلفيات وعادات ولغات مختلفة في الصف. والمطلوب من المعلم فيه أمران معاً: تنمية الاعتزاز بالدين والوطن، والتفاعل الإيجابي مع الثقافات الأخرى دون تنازل عن الثوابت.","استشهاد المعلم بمثال إيجابي من ثقافة أخرى **يعزز ثقافة احترام الآخرين**، وهذه العبارة نص أحد مؤشرات التنوع الثقافي في المعيار 1.2. ومن ثَمّ لا يُحسب في الأسئلة تعزيزاً للهوية الوطنية ولا إضعافاً لها.","أفعل استراتيجية لفهم التنوع **نشاط عملي** يعيشه الطالب، كالمقابلة أو المشروع المشترك أو عرض من زميل. أما الملصقات وقوائم الأعياد فأضعف أثراً؛ لأن الطالب يتلقاها ولا يعيشها.","**العزل حسب الثقافة** خطأ في كل الأحوال؛ إذ يناقض ما يطلبه المعيار من تفاعل إيجابي مع الثقافات الأخرى.","عند تفاوت مستوى اللغة في فصل متنوع الخلفيات، يجمع المعلم ذوي **المستوى المتقارب** في مجموعات صغيرة تؤدي أنشطة تناسبهم (المعيار 5.2). ويُعدّ بديل «إتاحة الحديث عن محتوى الدرس» مشتتاً؛ لأنه لا يعالج تفاوت المستويات.","يُعامَل الزميل غير المسلم **وفق مقتضيات مهام العمل** باتزان واحترام، فلا يُقاطَع، ولا يُدعى في كل لقاء، ولا يُحال إلى مراكز الدعوة. كما أن حسن المعاملة نفسه قدوة."]},{"h":"المواطنة الرقمية","pts":["**المواطنة الرقمية** هي الممارسة الآمنة والقانونية والأخلاقية للتقنية، ويحكمها نظام مكافحة الجرائم المعلوماتية (1428هـ) وباب التقنية في مدونة 1447.","من أخلاقيات المراسلة **تعريف النفس بوضوح**، ومراعاة حقوق النشر، والاعتذار عن الرسالة المرسلة خطأً. أما إخفاء الهوية، والتصرف في وثيقة وصلت خطأً، والرسائل المتكررة للتنبيه فكلها مخالفات.","صور الطلاب وبياناتهم أمانة، ولذلك يخضع نشرها لترتيب ثابت. أوله **مراجعة ما تتطلبه لوائح الوزارة** لنشر الصور، ثم أخذ إذن ولي الأمر، ثم النشر عبر القنوات الرسمية للمدرسة.","تمنع مدونة 1447 (المادة 21) المعلم من نشر مقطع لنشاط طلابه في حسابه الشخصي. وبدلاً من ذلك، يرفع النشاط إلى إدارة المدرسة لتنشره عبر قنواتها وفق ضوابط الوزارة.","تُعرف مصداقية الموقع الإلكتروني بـ**وجود معلومات مُعدّ الموقع وإمكانية التأكد منها**، لا بعدد الروابط فيه ولا بجمال العرض. فمعرفة المُعدّ هي التي تتيح التحقق من المحتوى."]}]},"L02":{"sec":[{"h":"الميثاق ومدونة 1447","pts":["ميثاق أخلاقيات مهنة التعليم الصادر عام 1427هـ **وثيقة قيم**، أما مدونة 1447 **فقواعد ملزمة** فيها واجبات ومحظورات. وتُعد المدونة المرجع الأدق إذا ذكر السؤال طلاباً أو أولياء أمور أو اختبارات.","عند الخلاف المهني بين المعلمين يكون الحل **مراجعة ميثاق** أخلاقيات مهنة التعليم؛ لأنه المرجع الوطني المعتمد، لا المواثيق العالمية ولا حكم المدير.","من أهداف الميثاق **تعزيز انتماء المعلم** لرسالته ومهنته والارتقاء بها، والإسهام في تعزيز **مكانة المعلم** العلمية والاجتماعية. وهي أهداف للميثاق، لا لسياسة التعليم.","**النمو المهني** في الميثاق **واجب أساس** على المعلم، لا خيار شخصي.","يقوم تعامل المعلم مع طلابه في الميثاق على **العدل** وصون كرامتهم، ومن ثَمّ يتجنب العقاب البدني والنفسي.","استجابة المعلم الإيجابية أو السلبية لمواقف مهنته تسمى **اتجاهه نحو المهنة**. وهو جانب وجداني يظهر مثلاً في مشاركته المستمرة الهادفة في نشاطات المدرسة."]},{"h":"سياسة التعليم 1390هـ","pts":["غاية سياسة التعليم، الصادرة بقرار مجلس الوزراء 779، **فهم الإسلام** فهماً صحيحاً متكاملاً. وتشمل الغاية كذلك غرس العقيدة، وتزويد الطالب بالقيم والمعارف والمهارات.","**اللجنة العليا** لسياسة التعليم تُقر الخطة التعليمية. أما إعداد المعلمين وتدريبهم وبناء المقررات فمهام تنفيذية لا تدخل في اختصاصها.","من مبادئ السياسة **التربية المتكاملة** التي تنمي جوانب شخصية الطالب كلها: الجسمية، والعقلية، والنفسية، والاجتماعية، والروحية. ولا يُخلط بينها وبين «التربية للحياة» أو «تكافؤ الفرص».","ومن مبادئها كذلك وضع **سياسة شاملة** لرعاية ذوي الاحتياجات الخاصة، دون تفضيل فئة منهم، كالموهوبين أو المعاقين ذهنياً، على غيرها.","**مستجد:** ألغاها قرار مجلس الوزراء 103، لكن أحكامها **سارية** حتى يُقر البديل خلال سنة من نفاذ النظام. وعليه فعبارة «أُلغيت فوراً» خطأ."]},{"h":"نظام التعليم العام 1448","pts":["نظام التعليم العام **منشور ولم يُطبَّق بعد**؛ إذ نُشر في 1448/2/10هـ، ويُعمل به بعد 180 يوماً تُحسب من تاريخ النشر، لا من تاريخ المرسوم.","يعمل **مجلس شؤون** التعليم العام، برئاسة وزير التعليم، **من تاريخ النشر**، أي قبل نفاذ بقية النظام. ومن اختصاصاته تحديد سن القبول.","وفق قواعد القبول المعلنة لعام 1448، يُقبل في الصف الأول الابتدائي من أكمل ست سنوات عند بداية العام الدراسي.","يمتد **الإلزام من 6 إلى 15** سنة (المادة 4)، أما **الطفولة المبكرة** فحتى نهاية الصف الثالث (المادة 1). ولا يُخلط بين الحدّين.","التعليم في النظام **حضوري**، والتقنية جزء منه لا بديل عنه؛ فلا يُقبل طلب الدراسة عن بُعد طوال العام بحجة توفر التقنية.","التعليم **مجاني في المؤسسات الحكومية** (المادة 3)، بعد أن كانت المجانية في سياسة التعليم تشمل أنواعه ومراحله كلها.","الأصل في تعليم ذوي الإعاقة **الدمج**، ولا يُلجأ إلى المراكز إلا لمن يتعذر دمجه منهم.","سياسة التعليم **«خطوط عامة»** للتعليم كله ومنه الجامعات، أما النظام **فأحكام ملزمة** خاصة بالتعليم العام. ومما أضافه النظام ولم تعرفه السياسة قائمة حقوق الطالب وباب الجزاءات."]},{"h":"الرخصة المهنية","pts":["**الرخصة** المهنية تصدرها **هيئة تقويم** التعليم والتدريب، لا وزارة التعليم. وتعمل معها لائحة الوظائف التعليمية التي تنظم الرتب والتعيين والترقية.","صارت الرخصة **إلزامية لمزاولة التعليم** منذ فبراير 2026، ويُعفى من هذا الإلزام من بلغ الخمسين قبل ذلك التاريخ.","صلاحية الرخصة **خمس سنوات**، ولا تُخلط بمدة التجربة للمعلم المعيَّن ابتداءً، وهي **سنتان**.","الدرجة المطلوبة لكل مستوى من مستويات الرخصة: 50 للممارس، و 70 للمتقدم، و 80 للخبير.","تُشترط درجة المستوى في **الاختبارين معاً**، مع سنوات الخبرة. مثال ذلك أن من حصل على 82 في التربوي و 74 في التخصص لا يتجاوز «متقدم»؛ لأن الدرجة الأدنى هي المعتبرة.","الاطلاع على **تقويم الأداء** الوظيفي والتظلم من نتيجته **حق** للمعلم. أما حضور الاجتماعات، والمشاركة في النشاط، ودراسة المناهج وتقويمها، فواجبات عليه."],"m":[5]},{"h":"السلوك والمواظبة 1447","pts":["للطالب من الصف الثالث الابتدائي درجتان منفصلتان: درجة **السلوك** 100، و**المواظبة 100 درجة**، ولكل منهما طريقة حسم.","تنقسم درجة السلوك إلى 80 درجة للسلوك الإيجابي يستحقها الطالب تلقائياً، و 20 درجة للسلوك المتميز يكتسبها بممارسات كالتسامح والأمانة.","**درجات الحسم** تتبع درجة المشكلة التي ارتكبها الطالب. ومع الحسم تُتاح له فرص تعويض، لكنها لا تعفيه من الإجراءات المقررة.","**التدرج** هو تطبيق الإجراء التالي عند تكرار المشكلة نفسها. أما إذا ارتكب الطالب أكثر من مشكلة في وقت واحد فتُتخذ إجراءات أعلاها درجة.","يُحسم من المواظبة درجة واحدة عن كل يوم غياب بلا عذر، ولا يُحرم الطالب بسببه من الاختبار مباشرة. غير أن تجاوز الغياب بلا عذر نسبة 10% يحرمه من الانتقال.","يُقدَّم عذر الغياب خلال **ثلاثة أيام عمل**، بينما يُشعَر ولي الأمر بالغياب في اليوم نفسه."],"m":[6]},{"h":"مواقف الالتزام بالأنظمة","pts":["عند اعتداء طالب على زميله بالضرب يبدأ الإجراء بـ**إشعار ولي الأمر** وأخذ تعهد خطي، ثم النقل إلى فصل آخر إن تكررت المشكلة. أما عقابه أمام زملائه فليس من الإجراءات المعتمدة.","تدخين الطالب خارج سور المدرسة يستوجب **إبلاغ المرشد الطلابي** ومدير المدرسة؛ لأن القواعد تشمل الشوارع المحاذية للمدرسة إذا رصد منسوبوها المخالفة فيها.","إذا طلبت جهة خارجية معلومات عن طالب فالخطوة الأولى **التحدث مع إدارة المدرسة** واتباع تعليماتها؛ إذ إن بيانات الطالب سرية، وإذنه وحده لا يكفي.","ولي الأمر الذي يريد أخذ ابنه أثناء الحصة يُحال إلى **إدارة المدرسة**؛ لأن الاستئذان إجراء إداري لا يملكه المعلم.","قواعد ضبط الصف، كرفع اليد قبل السؤال، تكون **متسقة مع قواعد الانضباط** التي أقرتها الوزارة، لا مع رأي الزملاء أو توقعات أولياء الأمور."],"m":[3]}]},"L04":{"sec":[{"h":"مجتمعات التعلم المهنية","pts":["**مجتمع التعلم المهني** فريق من المهنيين في المدرسة يعملون بتخطيط واستمرار، وغايته **تفعيل تعاون المعلمين** لتحسين تعلم الطلاب.","مبادئ مجتمع التعلم المهني أربعة: تشارك الرؤية والقيم والأهداف، وثقافة التعاون، والتركيز على تعلم الطلاب، والتركيز على النتائج.","مجتمع التعلم **عملي** يتناول مشكلات التدريس الفعلية في المدرسة؛ ولذلك يُعدّ القول إنه **يُعنى بالجوانب النظرية** مفهوماً خاطئاً عنه.","من **أوعية** مجتمع التعلم المهني: البحوث الإجرائية، والتوأمة المهنية، والتدريب بالأقران، والشبكات المهنية.","حين يراجع المعلمون أعمالهم معاً **تُحلّ مشكلات التدريس**؛ لأن تبادل الملاحظات يكشف للمعلم ما قد لا يراه وحده.","حضور المعلمين الجدد حصص زملائهم الخبراء صورة من صور **التطوير المهني**، إذ يوفر مجتمع التعلم للمستجدين البيئة الداعمة والإسناد.","يُشكَّل مجتمع التعلم من المعلمين بحسب **الصفوف التي يدرسونها**، لا بحسب أعمارهم أو سنوات خبرتهم.","يحلل مجتمع التعلم النتائج بحسب الأسئلة والفصول، لا بحسب أسماء المتفوقين؛ فيسأل: أين أخطأ الطلاب؟ ولماذا اختلفت الفصول؟","لا يكتفي مجتمع التعلم بتحليل النتائج، بل **يعدّل خطط التدريس** والأنشطة في ضوئها.","فائدة لقاء المعلمين المنتظم **تقديم تعليم مناسب** لجميع أنواع الطلاب ومستوياتهم، لا مكافأة المعلمين ولا المقارنة بينهم. مثال ذلك أن يتبادل معلمو الصف الخامس استراتيجيات لمساعدة من يجد صعوبة في الرياضيات.","يُعالَج الخلاف مع زميل، أو الغيرة من زميل متميز، **باقتراح مبادرات جماعية** للعمل كفريق، لا بتبليغ الإدارة ولا بالتعامل الرسمي البارد. ذلك أن العمل المشترك يحوّل التنافس إلى تعاون.","يُقابَل نقد الزملاء **بالصبر** لا بالانفعال، حفاظاً على العلاقة المهنية التي يقوم عليها مجتمع التعلم."]},{"h":"التفاعل مع أولياء الأمور","pts":["التواصل مع أولياء الأمور من **المسؤولية المهنية** للمعلم؛ ولذلك إذا حضر ولي الأمر إلى المدرسة استقبله المعلم واهتم بلقائه.","يقوم التعامل مع أولياء الأمور على ثلاثة مبادئ: الاستماع أولاً، واختيار وسيلة ثنائية الاتجاه للنقاش، وإحالة ما ليس من صلاحية المعلم إلى المختص أو الإدارة.","يبدأ المعلم مع ولي الأمر الغاضب **بالإنصات أولاً** ثم يعرض ما لديه؛ فشرح وجهة نظره ومراجعة اللوائح خطوتان لاحقتان.","إذا طلب المعلم مقابلة والد يرى أن ابنه عوقب ظلماً، أتاح له في بدايتها أن يعبّر عن رأيه ومشاعره وفهمه لما حدث. أما البدائل الأخرى فصحيحة، لكن توقيتها خاطئ.","ولي الأمر الغاضب من مستوى ابنه يُواجَه بهدوء ومنطق وحياد، وبأدلة من أعمال الطالب، لا برفع الدرجات إرضاءً له. فالدرجة ينبغي أن تعكس مستواه الحقيقي.","الأنسب لتبادل الآراء حول تقدم الطالب **عقد اجتماع** لمناقشة الأهداف المشتركة؛ لأن الملاحظات المكتوبة ودفتر المتابعة تواصل في اتجاه واحد.","إذا تدنّت نتائج صف كامل بُحثت في **مجالس أولياء الأمور**، لا في رسائل ومكالمات فردية؛ إذ تحتاج المشكلة العامة إلى لقاء جماعي.","هدف التقارير المرسلة إلى أولياء الأمور توضيح **مستوى الطالب وتقدمه**، لا إبراز جهود المعلم. ولذلك تُكتب بلغة بسيطة موجزة خالية من المصطلحات.","أول سؤال يطرحه كاتب التقرير على نفسه: ماذا أريد من ولي الأمر أن يعرف؟ وجوابه يحدد ما يدخل في التقرير.","إذا سأل ولي الأمر عن صعوبات التعلم لدى ابنه، فالإجراء الصحيح **طلب موعد اجتماع** مع مختص صعوبات التعلم؛ لأن التشخيص ليس من صلاحية المعلم.","عند شكوى ولي الأمر من التنمر يستمع المعلم إليه أولاً، ثم يتابع الحالة مع **الموجه الطلابي** (المرشد سابقاً)، بوصفه الجهة المختصة بها.","طلب ولي الأمر أخذ ابنه أثناء الحصة يُحال إلى إدارة المدرسة؛ لأنه إجراء إداري لا يقرره المعلم.","يُعان والد الطالب المخالف **بتزويده بلائحة** القواعد السلوكية، كي يدرّب ابنه عليها في المنزل.","مزايا اجتماعات أولياء الأمور **لا تشمل إشراكهم في تقويم المعلمين**.","ولي الأمر الذي يدعم التعليم يُمنح عضوية **مجلس المدرسة**.","يُطلع المعلم أولياء الأمور على **خططه التدريسية** وتعلم الطلاب وسلوكهم بتقنيات التواصل، مثل تطبيق ClassDojo؛ وبذلك يتابعون أبناءهم دون الحاجة إلى استدعائهم.","إذا أراد المعلم مخاطبة مدير المدرسة، فالصيغة المناسبة **خطاب إداري** رسمي."]},{"h":"معوقات التواصل","pts":["ينص مؤشر الممارس 3.2 على أن المعلم **يستخلص أبرز معوقات التواصل** مع أولياء الأمور، ويشارك في اللقاءات التي تستهدف التغلب عليها.","تأتي معوقات التواصل من جهتين: من الأسرة، كالوقت واللغة والتجربة السابقة؛ ومن المدرسة، كاستدعاء ولي الأمر عند المشكلات فقط.","يقابل كل معوّق حلٌّ مناسب، ومن الحلول: مرونة المواعيد، والرسائل الإيجابية الدورية، واللغة البسيطة، والإنصات قبل العرض، وتنويع القنوات، وإشراك الأسرة في الأنشطة.","يطلب سؤال الاختبار في الغالب **الحل** المناسب، لا اسم المعوّق نفسه؛ ولذلك يُحفظ كل معوّق مقروناً بحله.","إذا لم يستجب ولي الأمر **يُحلَّل السبب أولاً**: أهو الوقت أم اللغة أم تجربة سابقة؟ ثم يُختار الحل المناسب له، بدل تكرار الاستدعاء بالطريقة نفسها.","إذا غاب أغلب أولياء أمور صفٍّ عن اللقاءات المسائية بسبب أعمالهم، فالأنسب تنويع قنوات التواصل ومواعيده، كاللقاءات الافتراضية والرسائل الدورية، لا الاكتفاء بإرسال الدرجات النهائية.","تجعل قواعد 1447 من **دور الأسرة** حضور الاجتماعات ومجالس أولياء الأمور، والتواصل الفوري مع المدرسة عند غياب الابن.","**لجنة التوجيه الطلابي** هي التي تعقد مجلس أولياء الأمور، وفيه تُبحث القضايا العامة، كتدنّي نتائج صف كامل."],"m":[2]},{"h":"الشراكة مع المجتمع","pts":["**الشراكة المجتمعية** إسهام الأسر والمؤسسات بالفكر والمشورة والموارد في تطوير التعليم، وتنميتها هدف من أهداف رؤية 2030.","الشراكة علاقة **تبادلية** تأخذ فيها المدرسة من مجتمعها وتعطيه، أي أنها ليست دعماً في اتجاه واحد.","من **مقومات الشراكة** الاحترام المتبادل، وتقدير جهود المعلمين، والمسؤولية المشتركة بين المدرسة والأسرة والقطاعين العام والخاص والجامعات.","من نتائج الشراكة الناجحة اتجاهات أفضل نحو المدرسة، وتسرّب أقل، ومعنويات أعلى للمعلمين.","الأنشطة غير الصفية **اختيارية** تناسب ميول الطلاب؛ ولذلك يناقض فلسفتَها أن تُجعل إلزامية أو موحدة للجميع.","لا تُحصر الأنشطة غير الصفية داخل المدرسة، كما أن الأعمال المعروضة فيها من صنع الطلاب أنفسهم.","إذا كلّف المعلم طلابه بتنظيف الحديقة والمسجد المجاورين للمدرسة، فالأنسب **تكليف الطلاب بتقرير** عما عملوه وتقييمهم. أما مكافأتهم بالانصراف المبكر فتعزيز في غير محله.","مشاركة المعلم في فعاليات الحي **تكسبه خبرات** تدعم تعلم طلابه وتفاعلهم مع المجتمع، وتنسجم مع الميثاق الذي يعدّه عضواً مؤثراً في مجتمعه."]},{"h":"توظيف القضايا المحلية","pts":["ينص مؤشر 3.3 على أن المعلم **يتقصى القضايا المحلية** ويوظفها في التدريس بصورة تعزز وظيفة المعرفة. والمقصود أن يستعمل الطالب ما تعلمه ليفهم مشكلة في بيئته ويقترح لها حلاً.","للعمل بالمؤشر خطوتان، أولاهما **التقصي**، ومصادره الأخبار المحلية والإحصاءات الرسمية والأسر والمؤسسات القريبة.","الخطوة الثانية **التوظيف**، أي ربط القضية بهدف الدرس: بيانات حقيقية في الرياضيات، أو تجربة في العلوم، أو نص في اللغة.","لتوظيف القضايا المحلية ضوابط: أن تناسب القضية عمر الطلاب، وأن تخلو من التشهير بأشخاص أو جهات، وألا تتحول الحصة إلى موعظة.","يُثمر هذا التوظيف تعلماً ذا معنى، ويبني لدى الطلاب مسؤولية مجتمعية.","مثال ذلك: معلم رياضيات يدرّس النسبة المئوية لاحظ في نشرة محلية ارتفاع استهلاك المياه في الحي. والتوظيف الأنسب هنا أن يحسب طلابه نسب الهدر من بيانات أسرهم، ويقترحوا طرقاً للترشيد."]}]},"L07":{"sec":[{"h":"مبادئ النمو","pts":["النمو **تغيّر تقدمي منظّم** في جوانب متكاملة: الجسمية، والعقلية، والانفعالية، واللغوية، والاجتماعية، والأخلاقية. وهو محصلة **تفاعل الوراثة والبيئة**.","للنمو نوعان: **التكويني**، وهو زيادة في الحجم والشكل، و**الوظيفي**، وهو تحسّن أداء الأعضاء والقدرات.","النمو مستمر متتابع تراكمي، غير أن **معدلاته مختلفة**؛ فهو سريع في الطفولة المبكرة والمراهقة، وبطيء في الطفولة المتوسطة.","**اتجاه النمو** رأسي–ذيلي (الرأس قبل القدمين)، ومركزي–طرفي (الذراع قبل الأصابع)، ومن العام إلى الخاص (القبض بالكف قبل الالتقاط بإصبعين).","**النضج شرط للتعلم** لا العكس؛ فالنضج تغير داخلي يحدث دون تدريب، أما التعلم فتغير يحدث بالخبرة والممارسة.","التعليم قبل استعداد الطالب يضيّع الجهد ويولّد الإحباط. مثال ذلك أطفال في الثالثة لا ينجحون في الكتابة بين السطور؛ لعدم اكتمال نضجهم العضلي الدقيق، لا لضعف دافعيتهم.","يرى **جون لوك** أن الطفل يولد وعقله **صفحة بيضاء** تكتبها الخبرة. أما **روسو** فيرى أنه يولد خيّراً بطبعه وينمو نمواً طبيعياً حراً، وأن المجتمع هو الذي يفسده."]},{"h":"منظّرو النمو","pts":["يرى **بياجيه** أن الطفل **يبني معرفته بنفسه**، ويمر بأربع مراحل **ثابتة الترتيب**. ويختلف التفكير بينها نوعاً لا كماً، أي في طريقته لا في كمّ المعلومات.","عوامل الانتقال بين مراحل بياجيه أربعة: النضج، والخبرة، والتفاعل الاجتماعي، و**الموازنة**.","أولى مراحله **الحس-حركية** (0–2)، وفيها يبدأ **دوام الشيء** عند نحو 8 أشهر، ويكتمل في نهايتها. ومعناه إدراك أن الشيء موجود وإن غاب عن النظر.","تليها مرحلة **ما قبل العمليات** (2–7)، وفيها تظهر اللغة والرموز، مع **التمركز حول الذات** والإحيائية. ولا يعني التمركز الأنانية، بل العجز عن رؤية منظور الآخر.","ثم تأتي **العمليات المحسوسة** (7–11)، وفيها **الاحتفاظ** والمعكوسية، ثم **العمليات المجردة** (11 فأكثر)، وفيها التفكير الافتراضي.","طالب **الابتدائية** من الصف الثاني فما فوق (نحو 7 سنوات) في العمليات المحسوسة؛ ولذلك يتعلم بالوسائل المحسوسة والتجارب، لا بالتجريد اللفظي.","أما الصف الأول (6–7) فعلى حدود ما قبل العمليات، وعليه تُحدَّد مرحلته من السلوك الوارد في السؤال. فالإحيائية والتمركز علامتا ما قبل العمليات، والاحتفاظ والمعكوسية علامتا المحسوسة.","يرى **إريكسون** أن الإنسان يمر بثماني أزمات نفسية اجتماعية. وكل أزمة صراع بين قطب إيجابي وآخر سلبي، وحلّها إيجابياً يمهد للتي بعدها.","أزمة الابتدائية **الاجتهاد مقابل الدونية** (6–12)، وتسمى **الكفاية مقابل الشعور بالنقص**.","التشجيع وتقدير الجهد يبنيان الكفاية، أما النقد المتكرر فيولّد الدونية. ولذلك يُعطى الطالب المحبَط مهامّ متدرجة يقدر عليها، مع الاعتراف بإنجازه.","أزمة المراهقة **الهوية مقابل التشتت** (12–18)، ويناسب المراهقَ فيها إسنادُ الأدوار والمسؤوليات، واحترامُ استقلاليته.","قسّم **مارسيا** الهوية إلى أربع حالات: التشتت (لا استكشاف ولا التزام)، و**الانغلاق** (هوية يفرضها الوالدان بلا استكشاف)، والتعليق (استكشاف بلا التزام)، والتحقيق (استكشاف ثم التزام).","يتميز كل منظّر بجانب النمو الذي يدرسه: بياجيه **المعرفي**، وإريكسون النفسي الاجتماعي، وكولبرج الأخلاقي، وفرويد النفسي الجنسي، وهافجهرست مطالب النمو.","لكولبرج ثلاثة مستويات، في كل منها مرحلتان: ما قبل التقليدي (1 العقاب، 2 المصلحة المتبادلة)، والتقليدي (3 الولد الطيب، 4 القانون والنظام)، وما بعد التقليدي (5 العقد الاجتماعي، 6 المبادئ العالمية).","يقيس **كولبرج** **التبرير** وراء الحكم الأخلاقي لا الحكم نفسه، مستعملاً معضلات أخلاقية كمعضلة هاينز. فالممتنع عن الغش خوفاً من العقاب يقع في المرحلة 1، أما الممتنع لأن النظام يمنعه ففي المرحلة 4.","مراحل النمو النفسي الجنسي عند **فرويد**: الفمية، ثم الشرجية، ثم القضيبية، ثم **الكمون** (6–12)، ثم التناسلية. وفي الكمون، وهو سن الابتدائية، تهدأ الدوافع ويتجه الطفل إلى التعلم والأقران.","تتكون الشخصية عند فرويد من الهو، والأنا، و**الأنا الأعلى**؛ والأخير يمثل الضمير والمثل العليا.","**مطالب النمو** عند هافجهرست مهام تخص كل مرحلة، وإنجازها يمهد لما بعدها. ومنها في الطفولة المتوسطة: القراءة، والكتابة، والحساب، واللعب الجماعي.","**حيل الدفاع** عند فرويد أساليب لا شعورية يخفف بها الفرد قلقه.","**الإسقاط** أن ينسب الفرد مشاعره أو عيوبه إلى غيره؛ كطالب يكره زميله، ثم يقول: «هو الذي يكرهني».","**الإزاحة** تفريغ الغضب في هدف أضعف من مصدره. مثال ذلك طالب عاقبه المعلم أمام زملائه، فركل حقيبة زميل أصغر منه.","**التعويض** أن يسد الفرد نقصاً يشعر به بالتفوق في مجال آخر.","**التسامي** (الإعلاء) توجيه دافع غير مقبول كالعدوان إلى نشاط مقبول اجتماعياً؛ كطالب كثير العراك وُجّه إلى فريق الكاراتيه.","**النكوص** رجوع الفرد إلى سلوك يخص مرحلة عمرية سابقة."],"m":[1,2,3]},{"h":"المراحل الدراسية","pts":["**الطفولة المتوسطة (6–9)** تقابل الصفوف الأولية، ومن سماتها: الفضول، والتعلم بالمحسوسات، وقصر الانتباه. ولذلك تناسبها أنشطة قصيرة متنوعة تتخللها حركة، لا الجلوس الطويل.","**الطفولة المتأخرة (9–12)** تقابل الصفوف العليا، وهي سن الجماعة، وتتميز بروح العمل الجماعي. ومن ثَمّ يناسبها العمل في مجموعات، وإسناد أدوار قيادية.","**المراهقة المبكرة (12–15)** تقابل المرحلة المتوسطة، وفيها طفرة نمو وبلوغ تسبق فيه البنات الأولاد بنحو سنة إلى سنتين. كما يظهر فيها تقلب انفعالي، وأحلام يقظة، وبدء التفكير المجرد.","هذه المرحلة **أكثر المراحل حساسية للنقد القاسي**؛ لذلك يُناقَش المراهق على انفراد بالحوار والاحتواء، لا بالصدام.","جدال طالب المتوسطة في كل توجيه، وحرصه على موافقة أقرانه، سلوك طبيعي لمرحلة البحث عن الهوية والاستقلال. وعليه يُحتوى بالحوار، ولا يُعدّ اضطراباً يستدعي الإحالة.","**المراهقة المتوسطة (15–18)** تقابل الثانوية، وفيها يكتمل التفكير المجرد، وتتكون الهوية، وتظهر المثالية. فالأنسب لطلابها المشاريع والمسؤوليات والأدوار القيادية، مع ربط الدروس بالمهن المستقبلية."]},{"h":"الضغوط والإيذاء والإبلاغ","pts":["**الأحداث الضاغطة**، كالطلاق والوفاة والانتقال وولادة أخ والتنمر، قد تؤدي إلى تشتت الطالب أو تراجعه أو انسحابه أو عدوانه.","**العلامة التحذيرية** تغير مفاجئ عن حال الطالب السابقة، لا السلوك الطبيعي لمرحلته؛ كطالب متفوق تراجع تحصيله فجأة، وصار شارداً منطوياً بعد انفصال والديه.","يتعامل المعلم مع الطالب المتأثر بالترتيب الآتي: ملاحظة وتوثيق، ثم حوار فردي هادئ، ثم مرونة مؤقتة، ثم إحالة إلى الموجه الطلابي، ثم متابعة.","يوفر المعلم للطالب روتيناً ثابتاً وبيئة آمنة، ويلتزم **السرية** وعدم المقارنة؛ ولذلك لا يناقش ظروفه أمام زملائه.","الطالب المنتقل حديثاً يُعرَّف بالفصل، ويُعطى **زميلاً مرافقاً**، ثم يُشرَك تدريجياً.","من **مؤشرات الاضطراب الانفعالي**: الحزن المستمر، والانسحاب، والغضب غير المبرر، والشكاوى الجسمية بلا سبب طبي. غير أن العلامة الواحدة منها ليست دليلاً قاطعاً.","**الإيذاء** إساءة جسدية أو نفسية أو جنسية يتعرض لها الطالب، أو التهديد بها.","أما **الإهمال** فعدم توفير الحاجات الأساسية للطالب أو التقصير فيها. ويُعدّ انقطاعه عن التعليم إيذاءً أو إهمالاً.","ترتب **المادة 29** من قواعد السلوك والمواظبة إجراء الإيذاء. يبدأ بإبلاغ المدير فوراً وبسرية، ثم الإحالة إلى لجنة التوجيه الطلابي، ثم تدوين محضر رسمي، ثم استدعاء ولي الأمر.","إجراءات الإيذاء عاجلة وسرية، ولا تتدرج كالمخالفات السلوكية، بل تُتخذ بحسب خطورة الحالة؛ لأن الغاية سلامة الطالب.","تُبلَّغ الحالة العاجلة فوراً إلى **1919**، وهو رقم مركز بلاغات وزارة الموارد البشرية. ولأي من منسوبي المدرسة، إذا لاحظ تراخياً من إدارتها، أن يبلغ المركز مباشرة.","إذا كان مصدر الإيذاء من **منسوبي المدرسة** رُفعت الحالة إلى إدارة التعليم.","دور المعلم أن **يلاحظ ويوثق ويبلغ** المدير فوراً وبسرية، فلا يحقق ولا يواجه ولا يعد الطالب بالكتمان. ولذلك لا يتصل بالأسرة ليتحقق بنفسه من كدمات غير مفسرة."]}]},"L08":{"sec":[{"h":"الفروق الفردية والتعليم المتمايز","pts":["**الفروق الفردية** انحراف الفرد عن متوسط الجماعة في سمة ما. وهي فروق كمية في الدرجة لا في النوع، تتوزع توزيعاً اعتدالياً.","الفروق نوعان: فروق **بين الأفراد**، وفروق **داخل الفرد**، كأن يتفوق الطالب في اللغة ويضعف في الرياضيات.","تنشأ الفروق عن الوراثة والاستعداد الفطري، والعوامل **المكتسبة** من الأسرة والمجتمع. أما **أنماط التعلم** فمظهر للفروق لا سبب لها.","**أكبر مدى** للفروق في السمات الانفعالية والشخصية، ثم العقلية، وأقله في الجسمية.","السمات العقلية أكثر ثباتاً، ولهذا تبقى **نسبة الذكاء** ثابتة نسبياً؛ إذ تُقاس بأقران العمر.","مقياس «موافق بشدة… غير موافق بشدة» يقيس **الاتجاهات**، أي درجة قبول الطالب لموضوع أو رفضه له.","تُراعى الفروق بالتنويع والتعلم التعاوني والتعليم المبرمج، في حين أن **المحاضرة لا تراعيها**؛ لأنها تقدم المحتوى نفسه بالسرعة نفسها للجميع.","أوسع أساليب مراعاة الفروق **التعليم المتمايز** عند توملينسون. وفيه يبقى الهدف واحداً للجميع، ويتنوع المحتوى أو العملية أو المنتج أو البيئة بحسب استعداد الطلاب واهتماماتهم وأنماطهم.","يقوم التمايز على **مجموعات مرنة** تتغير بحسب المهمة، ولذلك يتعارض معه تقسيم الطلاب إلى مجموعات ثابتة دائماً."]},{"h":"أنماط التعلم والذكاءات","pts":["**أنماط التعلم** (VARK) طرائق الطالب المفضلة في استقبال المعلومات، وهي أربعة: البصري، والسمعي، والحسي الحركي، والقرائي الكتابي. فتقسيم الطلاب إلى بصري وسمعي وحسي تصنيف بالأنماط لا بالذكاءات.","ذكاءات **جاردنر** ثمانية: اللغوي، والمنطقي الرياضي، والمكاني، والجسمي الحركي، والموسيقي، والاجتماعي، والذاتي، والطبيعي. ويعدّها أنواعاً مستقلة نسبياً، لا قدرة واحدة.","يفصل بين **الذكاء الذاتي** والاجتماعي سؤال واحد: أهو فهم للذات أم للآخرين؟ فمن تتأمل نفسها ومشاعرها ذكاؤها ذاتي، أما من تقود زميلاتها وتفهمهن فذكاؤها اجتماعي.","تمر دورة **كولب** في التعلم بأربع مراحل: خبرة، ثم تأمل، ثم تجريد، ثم تجريب.","يبني نموذج **مكارثي** (4MAT) الدرس على أربعة أسئلة تناسب جميع الأنماط: لماذا؟ ماذا؟ كيف؟ ماذا لو؟","التطبيق الصفي للأنماط والذكاءات **تنويع** المداخل والعرض والأنشطة، لا حصر الطالب في نمط واحد. مثال ذلك عرض الدرس شرحاً شفهياً، ثم خريطة مفاهيم، ثم نشاطاً يدوياً."]},{"h":"العدالة والخلفيات","pts":["من مؤشرات المعيار 5.2 أن يميّز المعلم اختلافات طلابه الراجعة إلى خلفياتهم، وحاجات كل خلفية. والقاعدة الجامعة فيها **العدالة**: أن يُعطى كل طالب ما يحتاجه، لا الشيء نفسه للجميع.","**الخلفية الاقتصادية** المحدودة تفرّق الطلاب في خلفياتهم المعرفية وخبراتهم، لا في قدرتهم على التعلم. ولهذا تُراعى ببدائل منخفضة التكلفة ومصادر المدرسة، لا بإعفاء يحرمهم من التعلم.","**الخلفية الاجتماعية**، كتعليم الوالدين واستقرار الأسرة، تؤثر في الدعم المنزلي للطالب.","**الخلفية الثقافية واللغوية**، كحال الوافد أو من لغته الأم غير العربية، تتطلب أمثلة من بيئات متنوعة، وشرحاً للمفردات، ودعماً لغوياً، واحتراماً للعادات.","في الفصل المتفاوت لغوياً يجمع المعلم **ذوي المستوى المتقارب** في مجموعات صغيرة لأنشطة تناسبهم. أما إتاحة الحديث عن محتوى الدرس للجميع فلا تراعي اختلاف مستوياتهم.","**التدريس المستجيب ثقافياً** يجعل ثقافة الطالب جسراً للتعلم، مع توقعات عالية للجميع ودون قوالب نمطية. ومن ثَمّ فخفض المستوى المطلوب من الوافدين قالب نمطي، لا مراعاة."]},{"h":"صعوبات التعلم","pts":["ذو **صعوبات التعلم** ذكاؤه عادي وضعفه في مجال محدد، كمادة أو مادتين، أما **بطيء التعلم** فذكاؤه حدّي (70–85) وضعفه عام في جميع المواد.","**التأخر الدراسي** تدنٍّ مع ذكاء عادي، سببه خارجي، أي من خارج قدراته العقلية، كالغياب وإهمال الأسرة وضعف الدافعية.","تُشخَّص صعوبات التعلم **بمحك التباين** (ويسمى التباعد أو التفاوت)، وهو الفجوة بين قدرة الطالب العقلية وتحصيله الفعلي.","يُضاف إلى محك التباين **محك الاستبعاد**؛ فما نتج عن الإعاقات أو الظروف البيئية لا يُعدّ صعوبة تعلم.","سبب تدني ذي الصعوبات **اضطراب العمليات** الذهنية، كالانتباه والإدراك والذاكرة، لا انخفاض الذكاء ولا ضعف الدافعية.","صعوبات التعلم نوعان: **أكاديمية**، وهي الديسلكسيا في القراءة، والديسغرافيا في الكتابة، والديسكالكوليا في الحساب. أما صعوبات الانتباه والإدراك والذاكرة **فنمائية**، أي في العمليات نفسها.","يبقى ذو الصعوبات في الفصل العادي مع غرفة المصادر وخطة فردية، وتُكيَّف له المهام بنصوص أقصر ووقت أطول بدل إعفائه منها.","من طرق تدريس ذي الصعوبات **تعدد الحواس** (VAKT)، أي توظيف البصر والسمع والحركة واللمس معاً."],"m":[3]},{"h":"التوحد وفرط الحركة والإعاقات","pts":["**التوحد** قصور في التواصل والتفاعل، مع سلوك نمطي متكرر ومقاومة للتغيير. ويظهر في الطفولة المبكرة، غالباً قبل الثالثة.","بيئة ذي التوحد **التعلم المنظم** الثابت: روتين، وجداول بصرية، وتنبيه مسبق بأي تغيير. أما تغيير ترتيب الصف باستمرار حتى يعتاده فيزيد اضطرابه.","**فرط الحركة** ضعف انتباه ونشاط زائد واندفاعية. ولذلك يُجلس صاحبه قرب المعلم بعيداً عن المشتتات، ويُكلَّف بمهام قصيرة تتخللها حركة هادفة، فلا يُعزل ولا يُعاقب.","**الإعاقة الفكرية** ذكاء دون 70 تقريباً، ويقبل الدليل التنظيمي حتى 75 على مقياس وكسلر. وشرطها الثاني قصور في السلوك التكيفي يظهر في مرحلة النمو (قبل 18 في التعريف الشائع).","يُجلس ذو **الإعاقة السمعية** في المقدمة، ويواجهه المعلم عند الكلام، ويستعين بلغة الإشارة. أما ذو الإعاقة البصرية فيعتمد على **برايل**، ويصف له المعلم ما على السبورة لفظياً.","**الدمج** تعليم ذوي الاحتياجات الخاصة في المدرسة العادية مع أقرانهم العاديين، وأدنى أنواعه **المكاني** الذي يشاركونهم فيه المبنى والمرافق فقط. ويليه الاجتماعي الذي يضيف الأنشطة، ثم الأكاديمي في الفصل العادي جزئياً أو كلياً، ثم الشامل.","ذوو الاحتياجات الخاصة **يشملون الموهوبين**؛ إذ يُقصد بهم كل من ينحرف عن المتوسط ويحتاج إلى خدمات خاصة.","عند اشتباه إعاقة يلاحظ المعلم ويحيل إلى المختص، فلا يشخّص ولا يبلغ ولي الأمر بحكم غير مؤكد.","**الحبسة الكلامية** (الأفازيا) اضطراب لغوي مكتسب بإصابة دماغية. في **التعبيرية** يفهم المصاب، لكن يتعسّر عليه إخراج الكلام، أما في **الاستقبالية** فيتكلم بطلاقة كلاماً قليل المعنى ولا يفهم ما يُقال له."]},{"h":"الخطة الفردية والموهوبون","pts":["يمر الطالب قبل الخطة الفردية بمسار ثابت: ملاحظة، ثم إحالة، ثم موافقة ولي الأمر خطياً، ثم تشخيص. ولا يُكتفى في التشخيص بمقياس واحد.","**عناصر الخطة** الفردية أربعة: مستوى الأداء الحالي، ثم أهداف طويلة وقصيرة تُشتق منه، ثم الخدمات، ثم التقويم. والخطة **وثيقة متجددة** تُراجع كل عام أو نصف عام.","يُشترط في الهدف أن يكون قابلاً للقياس، مثل «يقرأ 20 كلمة بدقة 90% خلال 6 أسابيع». أما «يتحسن في القراءة» فمرفوض.","**لجنة الخطط** برئاسة قائد المدرسة، وتضم معلمَي التربية الخاصة والتعليم العام، والمرشد، وولي الأمر، والطالب قدر الإمكان. وليس منها المشرف التربوي للمادة.","**معلم التعليم العام** يكيّف التدريس، ويشارك معلم التربية الخاصة في إعداد الخطة وتقويمها.","من **الخدمات المساندة** في الخطة الفردية العلاج الطبيعي والنطق.","يُختار **المكان التربوي** في البيئة الأقل تقييداً: فصل عام، ثم غرفة مصادر، ثم فصل خاص، ثم معهد.","حلقات الموهبة عند **رنزولي** ثلاث: قدرة فوق المتوسط، وإبداع، والتزام بالمهمة. ولذلك لا يكفي الذكاء وحده.","يكون **الكشف** عن الموهوبين بمحكات متعددة، كالإبداع وترشيح المعلم، لا بالتحصيل وحده؛ لأن التحصيل المرتفع ليس من حلقات رنزولي الثلاث.","يفرّق **جانييه** (فرانسوا) بين الموهبة والتفوق: الموهبة استعداد فطري، والتفوق أداء مكتسب ينمو بالتدريب. ومن ثَمّ فكل متفوق موهوب، وليس كل موهوب متفوقاً.","من سمات الموهوب **الحساسية المفرطة** والكمالية وحس الدعابة. وقد يُفسَّر ملله خطأً على أنه سوء سلوك، مع أن سببه الحقيقي ضعف التحدي.","**الإثراء** يبقي الموهوب في صفه، فيعمّق خبرته (رأسي) أو يوسّعها (أفقي). ويكون **بمهام أعمق** لا بمزيد من التمارين نفسها؛ إذ يزيد التكرار ملله.","أما **التسريع** (التعجيل) فيغيّر مستوى الطالب أو زمن دراسته، بالقبول المبكر، أو تخطي الصف، أو ضغط المنهج بحذف ما أتقنه منه."],"m":[5]}]},"L09":{"sec":[{"h":"المفاهيم والسلوكية","pts":["**التعلم** تغير شبه دائم في سلوك المتعلم يكتسبه من الخبرة؛ فهو ما يحدث داخل الطالب، لا ما يفعله المعلم.","**التعليم** تصميم منظم للخبرة يقوم به المعلم ليساعد المتعلم على تغيير سلوكه.","**التدريس** إجراء قصير المدى ينفذه المعلم لأهداف محددة في موقف معين.","**التربية** أشمل هذه المفاهيم؛ لأنها تستهدف نمو الفرد كله.","**واطسون** مؤسس السلوكية، وهي ترى المتعلم متلقياً سلبياً يتعلم بالمثير والاستجابة.","صار جرس بافلوف بعد اقترانه بالطعام مرات عدة **مثيراً شرطياً** يستدعي اللعاب.","**الانطفاء** في الاشتراط الكلاسيكي أن يتكرر المثير الشرطي دون المثير الطبيعي فتضعف الاستجابة. أما **الاسترجاع التلقائي** فعودتها فجأة بعد راحة.","**التعميم** استجابة لمثيرات تشبه المثير الأصلي، وعكسه **التمييز**، أي الاستجابة للمثير الأصلي وحده.","قلق الاختبار عند السلوكيين **استجابة مكتسبة** لا فطرية؛ إذ ارتبط بموقف الاختبار عن طريق الخبرة.","**ثورندايك** فسّر التعلم بالمحاولة والخطأ، ووضع قوانين الأثر والتدريب والاستعداد.","**جاثري** صاحب قانون المرة الواحدة: يكفي اقتران واحد قوي للتعلم، كالخوف من النار بعد لسعة.","**انتقال أثر التعلم** موجب أو سالب أو صفري، وقد يكون أفقياً في المستوى نفسه، أو رأسياً كبناء الضرب على الجمع.","**سكنر** يرى السلوك الإرادي محكوماً بنتائجه، فالتعزيز بعد الاستجابة مفتاح التعلم. ومن تطبيقات نظريته **التعليم المبرمج**.","إذا أجاب الطالب صحيحاً بلا تعزيز فقلّت مشاركته، فهذا **انطفاء** في الاشتراط **الإجرائي**؛ لأن المشاركة سلوك إرادي.","إن سُئلت عن نظرية الانطفاء عموماً ولم يكن الإجرائي بين البدائل، فالجواب الاشتراط الكلاسيكي؛ إذ وصف بافلوف الانطفاء فيه أولاً.","في **جداول التعزيز** يكون المستمر أسرعها تعلماً وأسرعها انطفاءً، أما **النسبة المتغيرة** فأقواها وأكثرها مقاومة للانطفاء.","يرتفع الاستذكار قبيل الموعد في جدول **الفترة الثابتة**، في حين أن الاختبار المفاجئ فترة متغيرة تبقي الأداء منتظماً.","**التشكيل** تعزيز التقريبات المتتابعة، كمدح الخجول حين يرفع يده، ثم حين يجيب بكلمة.","**مبدأ بريماك** أن يعزِّز نشاطٌ محبب نشاطاً أقل تفضيلاً، كقول المعلم: «أنهِ الواجب ثم العب».","المعززات خمسة أنواع: غذائية، ومادية، واجتماعية (معنوية) كالابتسامة والمدح، ورمزية كالنجوم، ونشاطية كوقت اللعب.","**التصحيح الزائد** أن يصلح المخطئ ما أتلفه حتى يصير أفضل مما كان."],"m":[2]},{"h":"باندورا: التعلم بالملاحظة","pts":["**الحتمية التبادلية** أساس نظرية باندورا، وتعني التفاعل المتبادل بين الفرد وسلوكه وبيئته.","مراحل التعلم بالملاحظة أربع مرتبة: الانتباه، ثم الاحتفاظ، ثم الإنتاج (أداء السلوك)، ثم الدافعية.","النمذجة أنسب طريقة لتعلم **الاتجاهات والقيم**؛ إذ تُكتسب بملاحظة القدوة أكثر من التلقين.","**التعزيز البديل** أن يرى الملاحظ النموذج يُكافأ، فيزيد سلوكه هو دون أن يُكافأ مباشرة.","**الكفاءة الذاتية** اعتقاد الطالب بقدرته على مهمة محددة، وتُبنى بخبرات الإتقان لا بعبارة «أنت ذكي» وحدها.","**الانفصال الأخلاقي** تبرير الفرد سلوكه المؤذي، ومن آلياته التهذيب اللفظي، أي التسمية الملطفة كتسمية الاعتداء «مزاحاً»."]},{"h":"المعرفية ومعالجة المعلومات","pts":["**الجشطلت** ترى أن الكل أكبر من مجموع أجزائه، ومن قوانين الإدراك فيها الإغلاق.","التعلم عند الجشطلت **استبصار** مفاجئ بإعادة تنظيم الموقف، كما ركّب قرد كوهلر العصوين ليجلب الموز.","**تولمان** صاحب التعلم الكامن الذي يحدث بلا تعزيز، ويكوّن فيه المتعلم خرائط معرفية.","**أوزوبل** صاحب التعلم ذي المعنى، أي ربط الجديد بالبنية المعرفية، بخلاف الحفظ الصمّ دون ربط.","**المنظم المتقدم** تمهيد للدرس عند أوزوبل، كفيلم عن تجاذب الأجسام وتنافرها قبل درس الشحنات.","**التمايز التدريجي** عند أوزوبل انتقال من العام إلى الخاص، أما **التوفيق التكاملي** فربط المفاهيم وإزالة التناقض بينها.","يصنف أوزوبل التعلم في بعدين: تلقٍّ أو اكتشاف، وذو معنى أو استظهار.","**برونر** صاحب الاكتشاف الموجه والمنهج الحلزوني، الذي تعود فيه المفاهيم بعمق أكبر في كل صف.","يتدرج التمثيل عند برونر من عملي بالأشياء، ثم **أيقوني** بالصور والخرائط، ثم رمزي باللغة.","**هرم جانييه** يرتب ثمانية أنواع للتعلم، من **التعلم الإشاري** إلى **حل المشكلات**، وكل نوع شرط لما فوقه، فيبدأ المعلم بالمتطلبات السابقة.","**الانتباه** بوابة المعالجة في نموذج معالجة المعلومات، الذي يشبّه العقل بالحاسوب.","**الانتباه الانتقائي** تركيز على مثير واحد، بخلاف **الموزع** الذي يتجه إلى أكثر من مثير معاً.","الانتباه المتناوب تنقّل سريع بين مثيرين أو مهمتين، أما **القسري** فيفرضه مثير قوي مفاجئ كصوت الرعد.","تتسع الذاكرة قصيرة المدى لنحو 7±2 وحدات، وتبقى فيها المعلومة 15–30 ثانية دون تسميع.","**التجميع** يقلل عدد الوحدات، كتقسيم رقم طويل إلى ثلاث مجموعات؛ أما التسميع فتكرار.","**التداخل** القبلي أن يعيق القديم الجديد، والبعدي عكسه، ومثال البعدي نسيان الفرنسية بعد تعلم الإسبانية.","**الترميز المزدوج** (بايفيو) تخزين المعلومة لفظياً وبصرياً معاً، فتكون أقوى من تخزينها بشكل واحد.","**الحمل المعرفي** (سويلر) عبء المعالجة على الذاكرة العاملة، ويُخفف بتقسيم المحتوى إلى أجزاء.","**ما وراء المعرفة** (فلافل) تفكير في التفكير، كأن يسأل المعلم: «كيف توصلت إلى الإجابة؟».","**التدريب الموزع** على جلسات متباعدة أفضل للاحتفاظ من المذاكرة المكثفة ليلة الاختبار."],"m":[5]},{"h":"البنائية وفيجوتسكي","pts":["**منطقة النمو القريب** المسافة بين ما ينجزه الطالب وحده وما ينجزه بمساعدة الأكثر خبرة، وإليها يُوجَّه التدريس.","**السقالات** دعم مؤقت متدرج يُسحب مع تقدم المتعلم، فالدعم الدائم ليس سقالة.","**التمثل** عند بياجيه إدخال الجديد في المخطط القائم دون تغييره، كتسمية الطفل الحمار الوحشي «حصاناً مخططاً». أما **المواءمة** فتعديل المخطط أو بناء مخطط جديد.","المعلم البنائي ميسّر لا ملقّن، ينظم بيئة تعلم يبني فيها الطالب معرفته."]},{"h":"الدماغ والأساليب المعرفية","pts":["يقوم التعلم المستند إلى الدماغ على تحدٍّ **بلا تهديد**؛ لأن التعلم يتعزز بالتحدي ويُكبح بالتهديد.","**الاسترخاء اليقظ** من عناصر هذا التعلم، ويعني أماناً نفسياً مع تحدٍّ مرتفع.","**الأسلوب المعرفي** طريقة ثابتة نسبياً تصف كيف يتعلم الفرد لا مقدار ذكائه، ولا أسلوب أفضل مطلقاً.","المعتمد على المجال عند **ويتكن** يدرك الكل ويفضل الجماعة، في حين يحلل المستقل عنه الأجزاء ويفضل العمل الفردي.","المندفع عند **كاجان** سريع كثير الخطأ، والمتروّي متأنٍّ أقل خطأً.","نموذج **دن ودن** يربط أسلوب التعلم بعناصر بيئية وانفعالية واجتماعية وجسمية ونفسية."]}]},"L10":{"sec":[{"h":"الدافعية ونظرياتها","pts":["**الدافعية** حالة داخلية تحرك السلوك وتحافظ عليه، وأولى خصائصها **الغرضية**، وهي توجيه السلوك نحو هدف.","يُفرَّق في الدافعية بين **الدافع** وهو داخلي، و**الحافز** وهو خارجي بمعناه الشائع (المكافأة)، و**الباعث** وهو هدف يجذب السلوك.","الإفراط في المكافآت الخارجية يُضعف الدافعية **الداخلية** النابعة من المهمة نفسها. مثال ذلك طالب كان يرسم لمتعته، ثم صار يأخذ عليه درجات، فلما انقطعت توقف عن الرسم.","يصنّف **واينر** أسباب النجاح والفشل: القدرة داخلية ثابتة غير قابلة للضبط، والجهد داخلي متغير قابل للضبط، والحظ خارجي متغير، وصعوبة المهمة خارجية ثابتة.","عزو الفشل إلى الجهد يحفّز الطالب، في حين أن عزوه إلى القدرة يحبطه. فمن قال «أنا غبي في الرياضيات» عزا فشله إلى القدرة.","**العجز المتعلم** عند سليجمان توقف عن المحاولة رغم القدرة بعد فشل متكرر. أما **الإحباط** فانفعال مؤقت يقتصر على الموقف، كطالب مزّق ورقته غاضباً ثم واصل المحاولة في بقية المهام.","ينص قانون **يركس–دودسون** على أن أفضل الأداء عند استثارة متوسطة، أي عند قلق متوسط لا عند انعدامه.","يختار صاحب **دافع الإنجاز** المرتفع مهاماً متوسطة الصعوبة (ماكليلاند وأتكنسون).","**الكفاءة الذاتية** اعتقاد الفرد بقدرته على إنجاز مهمة محددة، وتُبنى بخبرات نجاح متدرجة.","تفضّل **دويك** توجه الإتقان (السعي إلى التعلم) على توجه الأداء (السعي إلى الظهور).","يتكون نموذج **كيلر** للدافعية من أربعة عناصر، أولها **الانتباه** الذي يُثار بالمفاجأة والتنويع.","بعد الانتباه تأتي **الصلة** بربط الدرس بحياة الطالب، ثم **الثقة** بمهام متدرجة، ثم الرضا بإعلان الإنجاز.","ترى نظرية **خفض الحافز** (كلارك هل) أن الحاجة تولّد حافزاً يدفع السلوك، فإذا أُشبعت انخفض الحافز وتعزز السلوك الذي أشبعها، كالأكل حين يشتد الجوع. والحافز هنا توتر داخلي، لا المكافأة الخارجية."],"m":[0]},{"h":"الذكاء: قياسه ونظرياته","pts":["وضع **بينيه** أول اختبار للذكاء (1905)، وإليه يُنسب مفهوم العمر العقلي.","مصفوفات **رافن** اختبار غير لفظي يناسب من لا يجيد اللغة.","**نسبة الذكاء** في صورتها الأولى تساوي العمر العقلي ÷ الزمني × 100، فمن عمره العقلي 10 والزمني 8 نسبة ذكائه 125. ومتوسطها 100، وتصنيفها في جداول المقارنة في آخر الملزمة.","يميز **كاتل** بين ذكاء سائل فطري يتراجع مع العمر، وذكاء متبلور مكتسب يزداد بالخبرة.","قال سبيرمان بعامل عام (g) في كل الأنشطة العقلية، إلى جانب عوامل خاصة.","يرى **ستيرنبرغ** أن الذكاء ثلاثي: تحليلي، وإبداعي، وعملي. ويسمّي الثلاثة مجتمعةً الذكاء الناجح.","نشر **جولمان** مفهوم الذكاء الوجداني (صاغه سالوفي وماير)، وهو فهم الانفعالات وإدارتها في النفس ومع الآخرين."],"m":[1]},{"h":"التفكير الناقد وحل المشكلات","pts":["مهارات التفكير العليا في تصنيف بلوم المعدل ثلاث: التحليل، والتقويم، والإبداع.","**التفكير الناقد** فحص المعلومات والحجج وتقويمها بمعايير، ومنطلقه الشك المنهجي لا الرفض.","مهارات التفكير الناقد عند واطسون وجليسر خمس: الاستنتاج، والتعرف على **الافتراضات**، والاستنباط، والتفسير، وتقويم الحجج.","التفكير الناقد يفرز الأفكار ويقوّمها، في حين أن الإبداعي يولّدها؛ فتوليد 20 فكرة إبداع، واختيار أفضل 5 منها نقد.","تقييم مواقع الإنترنت من حيث الدقة والمصداقية **تفكير ناقد**؛ لأنه حكم بمعايير.","**ما وراء المعرفة** عند فلافل تفكير في التفكير: تخطيط قبل المهمة، ومراقبة أثناءها، وتقويم بعدها.","تُنمّى ما وراء المعرفة بأسئلة مثل «كيف توصلت؟» وبجدول KWL. أما الحفظ والقراءة الصامتة فمهارات معرفية، لا ما وراء معرفية.","يبدأ **حل المشكلات** عند ديوي بالشعور بالمشكلة، ثم تحديدها، ثم وضع الفروض، ثم اختبارها، ثم الوصول إلى النتيجة.","خطوات حل المشكلات هي خطوات **التفكير العلمي** نفسها. أما التفكير التأملي فمراجعة الخبرة لتحسين الأداء.","**التفكير المركب** يضم التفكير الناقد، والإبداعي، وحل المشكلات، و**اتخاذ القرار**. ويُبنى على المهارات الأساسية كالملاحظة والمقارنة والتصنيف."]},{"h":"التفكير الإبداعي","pts":["أساس الإبداع عند جيلفورد **التفكير التباعدي**، أي توليد إجابات متعددة لمشكلة واحدة. أما التفكير التقاربي فيصل إلى إجابة واحدة صحيحة.","من مكونات الإبداع **الطلاقة** (عدد الأفكار) و**الأصالة** (ندرتها). فكثرة استخدامات القلم التي يذكرها الطالب طلاقة، والاستخدام الذي لم يذكره أحد أصالة.","مراحل الإبداع عند **والاس** أربع: الإعداد، ثم الاحتضان، ثم الإلهام، ثم التحقق.","**العصف الذهني** (أوزبورن) يقدّم الكم على الكيف ويرجئ الحكم، أي لا تُنقد الأفكار أثناء طرحها.","أكبر معوقات الإبداع النقد المبكر للأفكار، ومنها الخوف من الخطأ.","**الإثارة العشوائية** ربط مفهومين لا علاقة بينهما لتوليد أفكار جديدة، كسؤال «ما العلاقة بين المفتاح والمدير؟»"],"m":[3]},{"h":"برامج التفكير وعادات العقل","pts":["في **القبعات الست** لديبونو: البيضاء حقائق، والحمراء مشاعر، والسوداء مخاطر، والصفراء فوائد، والخضراء إبداع، والزرقاء ضبط التفكير وإدارته.","عبارة «أشعر أنها لا تعجبني» بلا تبرير من القبعة الحمراء، أما «ستفشل لأن التكلفة مرتفعة» فمن السوداء.","**برنامج كورت** لديبونو يعلّم التفكير مباشرة، ومن أدواته PMI: الإيجابيات، والسلبيات، والنقاط المثيرة للاهتمام.","يصف نموذج هيرمان أربعة أنماط للتفكير وفق السيطرة الدماغية: تحليلي، ومنظم، وعاطفي، وتخيّلي.","من الاستراتيجيات الصفية لتنمية التفكير **الأسئلة السابرة** التي تعمّق إجابة الطالب.","**عادات العقل** سلوكيات ذكية يلجأ إليها الطالب حين لا يعرف حل المشكلة فوراً، وهي عند كوستا وكاليك 16 عادة.","تُعرف العادة من سلوك الطالب، فمن يقرأ السؤال كاملاً قبل الحل يُظهر **التحكم بالتهور**.","**الاتجاه** استعداد مكتسب للقبول أو الرفض نحو موضوع، ومكوناته ثلاثة: معرفي، ووجداني، وسلوكي. مثاله في القراءة: الاعتقاد بأهميتها، ثم الشعور بالمتعة فيها، ثم الميل إلى استعارة الكتب.","يُعدَّل الاتجاه السلبي بخبرات نجاح متدرجة يعيشها الطالب، لا بالوعظ."],"m":[4]}]},"L11":{"sec":[{"h":"المدخل ومستوياته ومداخله الأربعة","pts":["تتدرج مفاهيم التدريس من الأعم إلى الأخص: **المدخل** فلسفة، ثم الاستراتيجية خطة مرنة، ثم الطريقة إجراءات يشترك فيها المعلمون، ثم الأسلوب.","**الأسلوب** بصمة المعلم الشخصية في تنفيذ الطريقة؛ فمعلمان يطبقان المناقشة نفسها يختلفان أسلوباً لا طريقةً.","**المدخل المنطقي** يرتب المحتوى من البسيط إلى المعقد، أما **السيكولوجي** فيرتبه وفق ميول المتعلم وحاجاته.","تُختار الطريقة لمناسبتها **لأهداف الدرس وخصائص الطلاب**، لا لشيوعها بين الزملاء.","في **مراكز التعلم** يتعلم الطلاب بأنفسهم، فيكون المعلم **ميسّراً** يدعمهم عند الحاجة.","صنّف **جويس وويل** النماذج في أربع عائلات: معالجة المعلومات، والاجتماعية، والشخصية، والسلوكية. ومن السلوكية التعليم المبرمج، والتعلم للإتقان، والتعليم المباشر.","تُعرف **الأسس النظرية** بعلاماتها: «خطوات وتعزيز فوري» سلوكي، و«اكتشاف بجهد الطالب» معرفي، و«يحدد أهدافه ويقوّم نفسه» إنساني، و«يحاكي زميلاً متقناً» اجتماعي.","من نماذج المدخل **المعرفي** الاكتشاف والاستقصاء و**المنظم المتقدم** لأوزوبل: مادة تمهيدية عامة، كفيديو قصير، تربط الدرس بما يعرفه الطالب."],"m":[0]},{"h":"طرق العرض المباشر","pts":["التعلم في طرق العرض المباشر **استقبالي**؛ إذ يتلقى الطالب المعرفة جاهزة.","**المحاضرة** تناسب الأعداد الكبيرة والمحتوى الكثيف، لكن المتعلم فيها متلقٍّ سلبي.","أبرز عيوب **المناقشة** سيطرة بعض الطلاب على الحوار وانسحاب آخرين.","**الاستقصاء العادل** مناظرة بين مجموعتين، مؤيدة ومعارضة، يحكم بينهما محكّمون.","**الحوار السقراطي** أسئلة متتابعة تقود الطالب إلى اكتشاف التناقض في رأيه.","**القصة** تناسب المرحلة الابتدائية؛ لأنها تقدم القيم في موقف حي.","**الاستقراء** يسير من الأمثلة إلى القاعدة، وهو أبطأ لكن أثره أطول. أما **الاستنباط (القياس)** فمن القاعدة إلى الأمثلة، وهو أسرع غير أن القاعدة قد تُنسى.","عرض أمثلة للفاعل حتى يستنتج الطلاب رفعه **استقراء** لا استنباط، رغم كلمة «يستنتج».","الطريقة الاستدلالية (**الهربارتية**) خطواتها: تمهيد، ثم عرض، ثم ربط، ثم استنتاج، ثم تطبيق. وتسميها أغلب المراجع الاستقرائية.","**العرض العملي** طريقة مباشرة يؤدي فيها المعلم المهارة بشرح متزامن، وتناسب التجارب الخطرة أو قليلة الأدوات."],"m":[2]},{"h":"المبرمج والتعلم الذاتي","pts":["**التعليم المبرمج** (سكنر) سلوكي: خطوات صغيرة، وتعزيز فوري، وخطو ذاتي يتقدم فيه كل طالب بسرعته.","**البرمجة الخطية** (سكنر) مسار واحد للجميع، أما **المتشعبة** (كراودر) فتحوّل المخطئ إلى إطار علاجي ثم تعيده.","من عيوب التعليم المبرمج أنه فردي **لا ينمي التفاعل الاجتماعي**، ولا يناسب الأهداف الوجدانية.","**التعلم الذاتي** يتحمل فيه المتعلم مسؤولية تعلمه دون تدخل مباشر من المعلم، ومن وسائله الحقيبة التعليمية والموديول.","في التعليم **الفردي** يؤدي كل طالب المهام نفسها منفرداً، في حين تختلف في **التفريدي** بحسب ميوله.","**عقد التعلم** اتفاق مكتوب يتعهد فيه الطالب بمهام محددة وفق معايير مقابل تقدير."],"m":[1]},{"h":"الاكتشاف والمشكلات والتغيير المفاهيمي","pts":["**الاكتشاف** (برونر) يصل فيه الطالب إلى المفهوم بنفسه، وغايته أن يتعلم كيف يصل إلى المعلومة.","في الاكتشاف الموجّه يحدد المعلم المشكلة والأدوات، أما في الحر فيحددها الطالب.","**الاستقصاء** أوسع من الاكتشاف؛ إذ يعمل فيه الطالب كالباحث. ويكون موجّهاً، أو شبه موجّه، أو حراً يحدد الطالب أدواته وخطواته.","**حل المشكلات** (ديوي): الشعور بالمشكلة، ثم تحديدها، ثم الفروض، ثم اختبارها، ثم النتيجة. وهي خطوات التفكير العلمي.","أول خطوات حل المشكلات **الشعور بالمشكلة** لا تحديدها، كتساؤل الطلاب عن سبب ذبول النباتات. أما اقتراحهم قلة الماء أو نقص الضوء فمرحلة الفروض لا اختبارها.","أول خطوات ديوي **الشعور بالمشكلة** لا تحديدها. أما اقتراح أسبابها المحتملة فمرحلة الفروض، لا اختبارها.","**المشروعات** (كلباترك) تنتهي غالباً بمنتج، بخلاف الاكتشاف الذي ينتهي إلى مفهوم.","في **دراسة الحالة** يحلل الطلاب موقفاً واقعياً ويقررون علاجه.","أكثر الطرق تطلباً **لفعالية المتعلم** الاكتشاف والمشروعات، وأقلها المحاضرة.","**التصورات البديلة** أفكار من خبرة الطالب تخالف العلم، وهي **مقاومة للتغيير** لأنها تبدو له منطقية. ولذلك لا يغيّرها غالباً شرح الصواب دون إحداث عدم الرضا.","شروط **التغيير المفاهيمي** (بوسنر) أربعة مرتبة: عدم الرضا عن التصور الحالي، ثم الوضوح، ثم المعقولية، ثم الإثمار.","**التدريب الاستقصائي** لسوشمان يعرض حدثاً متناقضاً، فيجمع الطلاب البيانات ويختبرون فروضهم بأسئلة جوابها **نعم أو لا**. ثم يفسرونه ويحللون طريقة استقصائهم."]},{"h":"الاستراتيجيات الاجتماعية","pts":["**التعلم التعاوني** مجموعات **غير متجانسة** من 4–6 طلاب. وأول عناصره الخمسة الاعتماد الإيجابي المتبادل، ثم المسؤولية الفردية، والتفاعل وجهاً لوجه، والمهارات الاجتماعية، ومعالجة عمل المجموعة.","البيئة **تنافسية** حين يرتبط فوز طالب بخسارة آخر، بخلاف التعاونية التي ينجح فيها الجميع.","إذا أنجز طالب واحد عمل المجموعة كله، فالعنصر الغائب **المسؤولية الفردية**. ويضمنها المعلم بتوزيع الأدوار والاختبار الفردي.","في **جيكسو** يدرس الخبراء جزءاً معاً، ثم يعود كل منهم إلى مجموعته الأم ليعلّمها إياه.","في **فرق التحصيل** (سلافين) يُختبر كل طالب فردياً، وتُحسب درجة الفريق من تحسن أعضائه.","قواعد **العصف الذهني** (أوزبورن) أربع: إرجاء النقد، وحرية التفكير، و**الكم قبل الكيف**، والبناء على أفكار الآخرين.","إذا تباطأت أفكار العصف سأل المعلم: «فكرة أخرى؟» لا «أفضل؟»؛ لأن المفاضلة حكم يناقض إرجاء النقد.","**التدريس التبادلي** يتبادل فيه الطلاب دور المعلم حول نص بأربع استراتيجيات: التنبؤ، وتوليد الأسئلة، والتوضيح، والتلخيص؛ لتحسين الاستيعاب القرائي وما وراء المعرفة.","**تدريس الأقران** طالب يعلّم زميله بإشراف المعلم، فيستفيد الاثنان.","**التدريس المصغر** تدريب للمعلم على مهارة واحدة مع عدد قليل من الطلاب.","**لعب الأدوار** لا يُقاطَع فيه المشهد، بل يُناقَش بعد انتهائه."],"m":[6]},{"h":"مخروط الخبرة والوسائل","pts":["رتّب **إدجار ديل** الخبرات في مخروط: قاعدته الخبرة المباشرة الهادفة، وقمته الرموز اللفظية المجردة.","**الوسائل التعليمية** أدوات ومواد تُكسب خبرات محددة، أما تقنيات التعليم فمنظومة أشمل تجمع الإنسان والآلة والطريقة.","تُعدّ **المحاكاة** بديلاً آمناً للتجارب الخطرة أو المكلفة."],"m":[7]}]},"L12":{"sec":[{"h":"مستويات الأهداف وصياغتها","pts":["**الغايات** أهداف بعيدة المدى تعبر عن فلسفة المجتمع ولا تُقاس في حصة، مثل «إعداد مواطن صالح».","بعد الغايات تأتي **الأهداف العامة** متوسطةَ المدى لمرحلة أو مقرر، ثم الأهداف **الخاصة السلوكية** قريبةَ المدى لدرس واحد.","**مصادر اشتقاق الأهداف** فلسفة المجتمع وحاجاته، والمتعلم، والمادة الدراسية، ونتائج البحوث التربوية. أما ميول المعلم الشخصية فليست منها؛ لأنها لا تصلح مصدراً لأهداف تخص الجميع.","مكونات الهدف السلوكي عند **ماجر** ثلاثة: سلوك، وشرط، ومعيار. ويُصاغ عادةً: أن + فعل سلوكي + الطالب + المحتوى + الشرط + المعيار.","يصف الهدف سلوك **المتعلم** لا سلوك المعلم؛ ولهذا تُرفض صيغة «يوضح المعلم…» مهما بدت مرتبة.","الهدف ناتج تعلم لا **نشاط**؛ فعبارة «يستخرج الفكرة الرئيسة» ناتج، بخلاف «يقرأ الدرس» الذي يصف نشاطاً.","في الهدف «أن يحل الطالب 8 مسائل من 10 دون آلة حاسبة» تمثل «8 من 10» **معيار** الإتقان، و«دون آلة حاسبة» **شرط** الأداء. والخلط بينهما فخ متكرر.","يُكتب الهدف بفعل قابل للملاحظة والقياس، مثل «يفسر» و«يعدد» و«يحل» و«يرسم». أما «يفهم» و«يدرك» و«يعتقد» فأفعال **غير قابلة للقياس**."]},{"h":"تصنيف بلوم","pts":["**صيغة المستويات** أسماء في بلوم الأصلي (1956)، وأفعال في المعدل عند أندرسون وكراثوول (2001).","أضاف التصنيف المعدل **بعد المعرفة** بأنواعه الأربعة: حقائقية، ومفاهيمية، وإجرائية، وما وراء معرفية.","يقابل **التركيب** في الأصلي الإبداعَ في المعدل، وقد تبادل موقعه مع التقويم، فصار الإبداع قمة المعدل.","يُصنَّف الهدف بفعله: «يفكك» **تحليل**، و«يحكم» و«ينقد» و«يبرر» تقويم، و«يصمم» و«يقترح» تركيب في الأصلي أو إبداع في المعدل.","أما «يقارن» و«يميز» و«يعلل» فتُصنَّف بحسب السياق: وصف الحقائق أو شرح سببها فهم، وتفكيك العلاقات تحليل.","المستويات الدنيا في بلوم التذكر والفهم والتطبيق، والعليا التحليل والتقويم والإبداع، وهي التي تستهدفها **أسئلة التفكير**."],"m":[1]},{"h":"الوجداني والنفس‑حركي","pts":["«أن يحب وطنه» و«أن يقدّر جهود العلماء» أهداف **وجدانية**؛ لأنها تصف قيمة أو اتجاهاً، لا معلومة أو مهارة.","في دليل الهيئة، المستويات **الدنيا** للوجداني الاستقبال والاستجابة والتقمص، و**العليا** التقدير والتنظيم والتجسيد. أما **التركيب** فمستوى معرفي لا وجداني.","للمجال **النفس‑حركي** عند سمبسون سبعة مستويات، أولها الإدراك الحسي وقمتها الإبداع. ويقسمه دليل الهيئة تقسيماً مدمجاً: الدنيا ملاحظة وتقليد وتجريب، والعليا ممارسة وإتقان وإبداع.","من التصنيفات الحركية الأخرى **ديف**، وأعلى مستوياته التطبيع، أي الأداء التلقائي دون تفكير. أما **هارو** فيبدأ تصنيفه بالحركات الانعكاسية."],"m":[2]},{"h":"ربط الأهداف بالمنهج","pts":["يطلب المؤشر 8.1 أنشطة بتسلسل منطقي تربط **أهداف التعلم بمعايير المنهج**.","تصف **معايير المحتوى** ما ينبغي تعلمه، في حين تصف **معايير الأداء** ما يُتوقع أن يؤديه الطالب في نهاية الصف.","التسلسل الصحيح: المعيار، ثم ناتج التعلم، ثم أهداف الدرس، ثم الأنشطة، ثم تقويم يجمع **دليلاً** على تحقق الهدف.","**التصميم العكسي** عند ويغنز وماكتاي يبدأ من النهاية: النتائج المرغوبة أولاً، ثم الأدلة المقبولة، ثم خبرات التعلم.","**المحاذاة** أن يكون الهدف والنشاط والتقويم في مستوى واحد؛ فهدف «يقارن» لا يُقوَّم بسؤال «اذكر» الذي يقيس التذكر."]},{"h":"التخطيط والتهيئة","pts":["**التخطيط** نوعان: طويل المدى سنوي أو فصلي، كتوزيع المقرر على أسابيع الفصل، وقصير المدى لخطة الوحدة أو للدرس اليومي.","يبدأ الدرس بالتحقق من **المتطلبات السابقة**؛ لأنها شرط لبناء التعلم الجديد.","**التهيئة** أربعة أنواع: حافزة تثير الاهتمام، وتوجيهية توجّه الانتباه إلى الموضوع، وانتقالية، وتقويمية. ويقابلها الغلق في الختام.","التهيئة **الانتقالية** تربط السابق بالجديد ولو بمراجعة قصيرة له، مثل «تعلمنا أمس… واليوم نتعلم». أما التقويمية فغرضها اختبار فهم السابق بأسئلة.","تبدأ أحداث جانييه التسعة للتدريس بـ**جذب الانتباه** قبل عرض المحتوى، وتنتهي بتعزيز الاحتفاظ والانتقال.","عند ضيق الوقت تُرتَّب الأنشطة **حسب أولويتها للأهداف** لا حسب سهولتها، ولا تُحوَّل كلها واجبات منزلية."],"m":[4]},{"h":"أدوات الخطة ومصادرها","pts":["**تحليل المحتوى** تفكيك المادة إلى حقائق ومفاهيم وتعميمات ومهارات وقيم واتجاهات، ويأتي بعد صياغة الأهداف وقبل اختيار الأنشطة.","في **هرم المعرفة** الحقائق جزئيات في القاعدة، والنظريات كليات في القمة. ومن ثَمّ يكون الصعود من الحقائق إلى النظريات استقراءً، والنزول منها استنباطاً.","**جدول المواصفات** يقاطع الموضوعات مع مستويات الأهداف ليحقق صدق المحتوى، أي أن يغطي الاختبار المحتوى والمستويات بأوزانها.","يُحسب الوزن **النسبي** للموضوع بهذه الصيغة: حصصه أو صفحاته أو أهدافه ÷ المجموع × 100.","**التغذية الراجعة** الجيدة فورية، ومحددة ووصفية، وتتناول المهمة لا شخص الطالب. أما المؤجلة فأقل أثراً.","أقوى صور التغذية الراجعة **تعليق محدد** يبين للطالب ما أحسنه، وما يحتاج إلى تحسين، وكيف يحسّنه، لا كلمة «أحسنت» وحدها.","إن جاءت البدائل: «**تعليق فقط**» و«تقدير وتعليق» و«درجة وتعليق»، فالأرجح علمياً «تعليق فقط»؛ إذ بيّنت دراسة **بتلر** (1988) أن إضافة الدرجة تلغي أثر التعليق. وإن غاب، فالأرجح التعليق المحدد ولو مع تقدير.","**الواجبات المنزلية** الجيدة مرتبطة بالدرس وهدفه، ومناسبة الكم، وتُصحَّح ثم تُعاد بتغذية راجعة، ولا تُستخدم عقاباً أبداً.","أول شروط المصادر الرقمية وغير الرقمية **الارتباط بالهدف**، ثم المناسبة للمتعلمين، والدقة، والأمان، والإتاحة للجميع، واحترام الملكية الفكرية.","المصدر **وسيلة** لا غاية، فالأحدث أو الأغلى ليس الأفضل بالضرورة. ويجرّبه المعلم قبل الحصة ويُعدّ له بديلاً.","**مصادر البيئة المحلية** فاعلة وقليلة التكلفة، ومن أمثلتها الزيارة، والعينات الحقيقية، والخبير من المجتمع.","نموذج **آشور** (هاينك وزملاؤه) ست خطوات: **تحليل خصائص المتعلمين**، ثم صياغة الأهداف، ثم اختيار الطرق والوسائط، ثم استخدامها، ثم إشراك المتعلمين، ثم التقويم والمراجعة."]}]},"L13":{"sec":[{"h":"التعلم النشط","pts":["**التعلم النشط** تطبيق عملي للنظرية **البنائية**؛ إذ يبني الطالب معرفته بالعمل، والمعلم فيه ميسّر لا ملقّن.","يطلب المؤشر 8.3 استراتيجيات تلبي **حاجات المتعلمين** وخصائصهم، كما أن تنويعها يخفض كره الطلاب للمادة.","**فكر‑زاوج‑شارك** (ليمان) يبدأ فردياً، ثم ثنائياً، ثم جماعياً. والترتيب مفتاح تمييزه في الأسئلة.","**الكرسي الساخن** تُوجَّه فيه الأسئلة إلى طالب واحد يجلس أمام الصف، بهدف تنمية مهارات بناء الأسئلة وتبادل الأفكار.","جدول **KWL** (أوجل) ينشّط المعرفة السابقة، وينمّي **ما وراء المعرفة** لا التفكير الإبداعي؛ لأن الطالب يراقب به ما يعرفه، وما يريد معرفته، وما تعلمه.","في **الصف المقلوب** يكون الشرح في المنزل والتطبيق في الفصل؛ لاستثمار وقت الحصة في التفاعل والمهام العليا.","**دورة التعلم 5E** (بايبي) تبدأ بالانشغال وتنتهي بالتقويم، ويأتي فيها الاستكشاف قبل الشرح. ومراحلها الخمس في جداول المقارنة في آخر الملزمة.","التعلم **القائم على المشكلات** يبدأ بمشكلة غير محددة البنية بلا حل واحد، بخلاف القائم على المشروعات الذي ينتهي بمنتج.","التعلم **للإتقان** (بلوم وكارول) لا انتقال فيه قبل إتقان 80 إلى 90%، وقاعدته أن **الزمن متغير** والتحصيل ثابت للجميع.","من الاستراتيجيات التفاعلية **مراكز التعلم**، ويتنقل الطلاب بينها بالتناوب.","نموذج التغير المفاهيمي (**بوسنر**) من النماذج البنائية، ويعالج التصورات البديلة لدى الطلاب.","أبعاد التعلم عند **مارزانو** خمسة. والمقارنة والتصنيف من بُعد **تعميق المعرفة وصقلها**، في حين أن حل المشكلات من بُعد الاستخدام ذي المعنى.","استراتيجية **روبنسون** (SQ3R) لفهم المقروء خمس خطوات: المسح، ثم تحويل العناوين إلى أسئلة، ثم القراءة بحثاً عن الإجابة، ثم التسميع بأسلوب الطالب، ثم المراجعة."],"m":[0]},{"h":"التمايز والخرائط والأسئلة","pts":["**التعليم المتمايز** (توملينسون) يكيّف المحتوى والعملية والمنتج والبيئة وفق استعداد الطلاب واهتماماتهم وأنماط تعلمهم، لكن الهدف واحد للجميع.","معادلة التمايز: هدف واحد ومهام متنوعة تؤدي إلى **نفس المخرجات**. أما التعليم التقليدي الذي يراعي الفروق فمهمة واحدة يقبل فيها المعلم مخرجات مختلفة.","إتاحة إظهار التعلم بمقال أو عرض تقديمي أو فيلم قصير تمايز في **المنتج**.","**خريطة المفاهيم** (نوفاك) هرمية يوضع العام في قمتها، وأساسها نظرية التعلم ذي المعنى عند **أوزوبل**.","**الخريطة الذهنية** (بوزان) شعاعية حول فكرة مركزية، بخلاف خريطة المفاهيم الهرمية.","الأسئلة **المفتوحة** لا تبحث عن إجابة واحدة، وهي التي تستثير التفكير وتحفز النقاش.","يُطرح السؤال أولاً، ثم يُختار المجيب؛ ليبقى الجميع مفكرين.","**زمن الانتظار** (رو) من 3 إلى 5 ثوانٍ بعد السؤال وقبل اختيار المجيب، وهو يرفع جودة الإجابات.","**الأسئلة السابرة** تتبع الإجابة بحسب نوعها: الناقصة بسؤال توضيحي، والخاطئة بسبر مشجع لا تصحيح فوري، وعدم الإجابة بإعادة صياغة.","وصف العمليات والصعوبات في آخر الدرس ينمّي **التأمل** وما وراء المعرفة، أي التفكير في التفكير."]},{"h":"التعليم الشامل","pts":["**الدمج** يطلب من الطالب ذي الاحتياج أن يتكيف مع النظام القائم، أما **الشمول** فيغيّر النظام نفسه ليستوعب التنوع.","**التعليم الشامل** تعليم الجميع معاً في الفصل العام، ومن ممارساته التعاون مع معلم التربية الخاصة.","الشمول **ليس** خفضاً للأهداف ولا عزلاً لذوي الاحتياج، وإنما يتخذ التمايز أداةً ليصل إلى كل طالب.","**التصميم الشامل للتعلم** (UDL) **تخطيط مسبق** بوسائل متعددة للتمثيل والتعبير والمشاركة، تُجهَّز من بداية الدرس لا بعد ظهور المشكلة.","مثال ذلك درس يُقدَّم بنص ومقطع مرئي ومجسم، فيناسب ضعيفة السمع والموهوبة معاً."]},{"h":"التقنية في التعليم","pts":["مستويات توظيف التعلم الإلكتروني: **المساند** الذي يدعم التعليم الصفي دون تغيير بنيته، ثم **التعليم المدمج** الذي يجمع الحضوري والإلكتروني، ثم الكامل عن بعد.","التعليم المتزامن يجري في الوقت نفسه ولو اختلفت الأماكن، أما غير المتزامن ففي أوقات مختلفة كالشرح المسجل.","التعلم المتنقل يعتمد على الأجهزة المحمولة كالهواتف الذكية، دون قيد بالمكان أو الزمان.","نموذج **SAMR** (بونتيدورا) يقيس عمق أثر التقنية: الاستبدال، ثم التعزيز، ثم التعديل، ثم إعادة التعريف بمهمة مستحيلة دون تقنية.","نموذج **TPACK** (ميشرا وكوهلر) يصف تكامل معارف المعلم في التقنية والتربية والمحتوى.","نموذج ADDIE أشهر نماذج التصميم التعليمي، ويبدأ بالتحليل ثم التصميم ثم التطوير ثم التنفيذ، وينتهي بالتقويم.","من منصات الوزارة: **مدرستي** للفصول الافتراضية والواجبات، و**نور** للدرجات والغياب والشهادات، وعين للمحتوى الرقمي والقنوات، وروافد للمصادر.","**الويب كويست** (الرحلات المعرفية) بحث عبر الإنترنت في مصادر أعدها المعلم مسبقاً، لا رحلة ميدانية خارج الصف.","**الحوسبة السحابية** تخزين على خوادم الإنترنت يتيح تحرير الملفات معاً عن بعد. أما الذاكرة المحمولة (الفلاش) فتخزين محلي ليس منها.","من **مبادئ ماير** وضع النص قرب الصورة، والتعليق الصوتي مع الرسوم، وحذف المشتتات.","الواقع المعزز يضيف عناصر رقمية إلى مشهد الواقع الحقيقي.","مدخل **ستيم** يدمج العلوم والتقنية والهندسة والرياضيات في مشروع واحد، يصمم فيه الطلاب حلاً ثم يجربونه ثم يحسّنونه."],"m":[3]},{"h":"المنهج وتنظيماته","pts":["**المنهج** بمفهومه الحديث **جميع الخبرات** المخططة داخل المدرسة وخارجها، فهو أعم من المقرر، والمقرر أعم من الكتاب.","عناصر المنهج: الأهداف، ثم المحتوى، ثم طرق التدريس والأنشطة، ثم التقويم الذي يتحقق من بلوغ الأهداف.","أسس المنهج: الفلسفي (العقدي)، والنفسي، والاجتماعي، والمعرفي. أما الإداري فليس منها؛ لأن الإدارة تنفيذ لا أساس.","المنهج بوصفه **نظاماً** يتكون من مدخلات (أهداف ومحتوى)، وعمليات (طرق وأنشطة)، ومخرجات، وتغذية راجعة (تقويم).","المنهج **الخفي** (جاكسون) يُتعلَّم ضمناً دون تخطيط، كاحترام الوقت الذي يتعلمه الطلاب من معلم يحضر قبل الجرس.","المنهج **الفارغ** أو الصفري (آيزنر) ما لا يُدرَّس، عمداً كان أو سهواً، كموضوع حذفته لجنة المناهج.","المنهج **المحوري** يدور حول حاجات الطلاب ومشكلاتهم المشتركة، ومعه مواد اختيارية بحسب ميول الطالب واهتماماته.","منهج **النشاط** (ديوي) يقوم على ميول الطلاب، ويُبنى على حل المشكلات.","المنهج **الحلزوني** (برونر) يعود إلى المفاهيم نفسها مرة بعد مرة، بعمق متزايد.","**نموذج تايلر** يبدأ بالأهداف ثم الخبرات ثم تنظيمها ثم تقويمها. وتايلر كذلك صاحب النموذج الأشهر في تقويم المنهج.","نموذج تابا استقرائي يبدأ من المعلم بتشخيص حاجات الطلاب، بخلاف تايلر الذي يبدأ بالأهداف.","التنظيم **المنطقي** يتبع بنية المادة من البسيط إلى المعقد، أما السيكولوجي فيرتب المحتوى وفق حاجات المتعلم وميوله.","**المدى والتتابع**: المدى **أفقي** يصف اتساع المحتوى في الصف الواحد، والتتابع **رأسي** يصف تدرجه عبر الصفوف. ومن المدى ربط المواد كالرياضيات بالعلوم."],"m":[4]},{"h":"الأبعاد المشتركة","pts":["الأبعاد **المشتركة** قيم ومهارات لا تختص بها مادة بعينها، فتُنمّى عبر **جميع المواد** بصفة مباشرة أو ضمنية.","تتكون الأبعاد المشتركة في نص المعيار الثامن من **أولويات**، وقيم ست، ومهارات.","من الأولويات التنمية المستدامة، أي تلبية حاجات الحاضر دون الإضرار بقدرة الأجيال القادمة على تلبية حاجاتها.","**الشغف المعرفي** من القيم الست، وهو حب الاستطلاع والرغبة الذاتية في المعرفة.","تشيع في أسئلة المواقف قائمة مختصرة للأبعاد، منها الثقافة الرقمية، أي الاستخدام الآمن والأخلاقي للتقنية. لكن نص المؤشرات المعتمد هو الأولويات والقيم والمهارات.","**المواطنة الرقمية** قواعد ومعايير توجه الأفراد إلى منافع التقنية، وتحميهم من أخطارها."],"m":[5]}]},"L14":{"sec":[{"h":"التوقعات والدافعية","pts":["توقع المعلم العالي يعكس **إيمانه بقدرة** جميع طلابه على النجاح، لا رغبته في التنافس أو في إنجاز شخصي.","**أثر بجماليون** (روزنثال وجاكوبسون) أن يصير توقع المعلم **نبوءة تحقق ذاتها**؛ إذ ينتظر إجابة من يتوقع منه الكثير وقتاً أطول، ويكلفه بمهام أصعب، فيرتفع أداؤه.","التوقع العالي تحدٍّ يرافقه دعم و**أهداف تعلم واضحة**، بخلاف التوقع المثالي غير الواقعي الذي يُحبط الطالب بتكرار تجربة الفشل.","يُقارَن الطالب **بأدائه السابق** لا بأقرانه؛ ذلك أن مقارنته بنفسه تكشف تقدمه الفعلي، وتبني دافعيته الداخلية.","**العزو** عند واينر تفسير الطالب لسبب نجاحه أو فشله. فإذا عزا فشله إلى قلة الجهد زادت مثابرته؛ لأن الجهد سبب يتحكم فيه.","أما عزو الفشل إلى ضعف القدرة الثابتة فيولّد **العجز المتعلم**؛ ولذلك يعيد المعلم توجيه عزو الطالب إلى مهارة تتحسن بالتدريب.","**الكفاءة الذاتية** عند باندورا ثقة الطالب بقدرته على إنجاز المهمة، وأقوى مصادرها **خبرات الإتقان**، أي نجاحه الفعلي في مهام سابقة.","يُرفع تقدير الذات بإبراز جوانب القوة، وبمهام ينجح فيها الطالب، لا بخفض المطلوب منه؛ إذ يوحي خفضه بأن المعلم لا يثق بقدرته.","بعد الإجابة الخاطئة يلجأ المعلم إلى **إعادة صياغة السؤال**، لا إلى تقديم الإجابة الجاهزة؛ لأنها تُنهي تفكير الطالب، بينما تمنحه إعادة الصياغة فرصة ثانية.","كما يبني المعلم على الجزء الصحيح من الإجابة، ثم يستعمل **السبر المشجع**، أي أسئلة متتابعة تقود الطالب إلى الصواب دون إحراج."]},{"h":"قيادة الصف","pts":["إدارة الصف **تنظيم البيئة التعليمية** ليحدث التعلم، لا مجرد ضبط ومعاقبة. والإدارة الفعالة تهيئ فرصاً ليصبح الطلاب متعلمين مدى الحياة، في تعلم تعاوني يسوده الاحترام.","أنسب أنماط إدارة الصف **الديمقراطي**؛ لأنه يجمع بين ضوابط واضحة ومشاركة الطلاب. أما الود بلا ضوابط فنمط فوضوي لا ديمقراطي.","**القواعد الصفية** قليلة (من 3 إلى 5) ليسهل تذكرها، وإيجابية الصياغة، أي تصف السلوك المطلوب بدل تعداد الممنوعات.","توضع القواعد **مع الطلاب** في بداية العام متسقةً مع قواعد الوزارة، وتُراجع عند الحاجة. ويُشرح لهم نفعها؛ لأن من يفهم سببها يلتزم بها ذاتياً.","وجد **كونين** أن الانضباط يصنعه سير الدرس لا العقوبات. ومن مفاهيمه **اليقظة**، وهي وعي المعلم بكل ما يجري في الصف.","إذا شرد عدد من الطلاب أثناء الشرح، فالأنسب نشاط قصير يكسر الروتين ويعيد انتباههم؛ إذ لا يعالج التهديد ولا التغافل سبب الشرود.","تُرتَّب المقاعد بحسب **نوع النشاط**: صفوف للعرض، ومجموعات للتعاون، وحرف U للنقاش.","تكون المجموعات غير متجانسة بأدوار محددة، أما المعلم فهو **ميسّر** يتنقل بينها ويدعم عند الحاجة.","**الأزمة الصفية** لها ترتيب ثابت: الهدوء أولاً، ثم فصل المتسببين، ثم شغل البقية بنشاط، ثم المعالجة الفردية بعد الحصة لا أمام الصف."],"m":[1]},{"h":"القدوة وقواعد السلوك","pts":["يكمل المعلم قيادة صفه بأن يكون **القدوة الحسنة**؛ إذ يتعلم الطلاب مما يفعله أكثر مما يقوله.","يلتزم المعلم **حدود العلاقة المهنية**، وتعني وداً عادلاً مع الطلاب جميعاً، بلا محاباة ولا مزاحٍ يمس كرامتهم.","إذا أخطأ المعلم أمام طلابه، فالأنسب أن **يعترف ويعتذر** ويصحح خطأه أمامهم بلا حرج؛ لأن ذلك يبني الثقة ولا يُضعف مكانته.","يباشر المعلم **الإجراءات الثلاثة الأولى** من مشكلات الدرجة الأولى: تنبيه شفهي، ثم تنبيه ثانٍ مع حصر الأسباب، ثم التدوين وإشعار ولي الأمر. ومن لم يستجب أحاله إلى الإدارة عبر وكيل شؤون الطلاب.","تمنع المادة 28 من قواعد السلوك **نسخ الواجب عقاباً**، وإقصاء الطالب خارج الصف، وإيذاءه والسخرية منه؛ لأن هذه الأساليب تمس كرامته أو تحرمه من التعلم.","**المسميات الحالية** هي: الموجه الطلابي، ولجنة التوجيه الطلابي. أما «المرشد» و«لجنة التوجيه والإرشاد» فمسميان سابقان للجهتين نفسيهما."],"m":[4]},{"h":"تعديل السلوك","pts":["**التعزيز** يزيد السلوك، بينما يقلله **العقاب**. والموجب فيهما إضافة شيء، والسالب إزالة شيء، وليس المقصود بهما الجيد والسيئ.","مثال ذلك إلغاء إنذار سابق بعد التزام الطالب؛ فهو **تعزيز سالب** لا عقاب، لأنه أزال أمراً مزعجاً ليزيد الالتزام (انظر جداول المقارنة في آخر الملزمة).","التعزيز الفعال **فوري** يأتي بعد السلوك مباشرة؛ إذ يُضعف التأخير ارتباط المعزز بالسلوك.","يُستعمل التعزيز المتواصل لاكتساب السلوك، أما **المتقطع** فللمحافظة عليه بعد اكتسابه. فالمعلم يعزز السلوك في كل مرة عند تعلمه، ثم يباعد بين مرات التعزيز حين يثبت.","أسهل المعززات وأكثرها استخداماً في الصف **الاجتماعية** (وتسمى معنوية)، كالثناء والابتسامة؛ لأنها لا تكلف شيئاً.","**الانطفاء/الإطفاء** حجب التعزيز بالتجاهل المقصود حتى يتلاشى السلوك، ويُقرن **بالتعزيز التفاضلي** للسلوك البديل. وقد يزيد السلوك مؤقتاً في البداية.","التجاهل انطفاء لا عقاب؛ فالعقاب السالب سحب معزز موجود، في حين أن التجاهل حجب للتعزيز. مثال ذلك أن يتجاهل المعلم من يصيح «أنا أعرف!»، ويشكر من رفع يده.","**تكلفة الاستجابة** فقدان معزز مكتسب، كخصم نقاط أو امتياز. أما الإقصاء المؤقت فعزل عن البيئة المعززة، كإجلاس الطالب جانب الملعب دقائق.","كلا الأسلوبين **عقاب سالب** يسحب معززاً موجوداً، غير أن إقصاء الطالب خارج الصف ممنوع بنص المادة 28.","**التصحيح الزائد** إصلاح الضرر مع عمل إضافي، كالاعتذار وإحضار مقعد جديد. أما دفع الطالب ثمن ما كسره من مصروفه فهو **تكلفة استجابة**؛ لأنه فقدان شيء يملكه.","**مبدأ بريماك** أن يُشترط النشاط المحبب بإنهاء نشاط أقل حباً، كأن يقول المعلم: «من ينهي التمارين يختار القصة».","**الاقتصاد الرمزي** رموز يجمعها الطالب، كالنجوم أو النقاط، ثم يستبدلها بمعززات متفق عليها.","من أساليب تعديل السلوك **العقد السلوكي**، وهو اتفاق مكتوب يحدد السلوك المطلوب ومكافأته.","**التشكيل** تعزيز التقريبات المتتابعة نحو السلوك، أما **التسلسل** فتعزيز كل حلقة من حلقاته. مثال التشكيل تعزيز الطالب الصامت حين يجيب بكلمة، ثم بجملة.","**النمذجة** تعلم السلوك بملاحظة نموذج يؤديه، كأن ينفذ المعلم خطوات التجربة أمام طلابه ثم يقلدونه.","**التلقين** تلميح يعين الطالب على أداء السلوك، وقد يكون لفظياً أو إيمائياً أو جسدياً كالإمساك باليد.","**التحصين التدريجي** تعريض متدرج لما يخيف الطالب من الأسهل إلى الأصعب، بخلاف **الغمر** الذي يواجهه بما يخيفه دفعة واحدة.","**ضبط المثير** تغيير البيئة التي تثير السلوك، كنقل مقعد الطالب الذي يتحدث مع جاره."]},{"h":"البيئة الآمنة والسلامة","pts":["إذا وقع العنف اللفظي أول مرة، بدأ المعلم **بتنبيه المعتدين** إلى أن سلوكهم مرفوض وله عواقب إن تكرر. أما إبلاغ الإدارة والأهل فخطوة لاحقة.","**التنمر** يُعالج بخطة مدرسية يشترك فيها الموجه والإدارة والأسرة؛ إذ يحتاج علاجه إلى متابعة تتجاوز حدود الحصة.","**المعتدى عليه** يُحمى ولا يُلام، ولا يُواجَه بالمتنمر أمام الصف؛ لأن لومه أو مواجهته علناً يضاعف أذاه.","إذا اشتكى ولي أمر من التنمر، بدأ المعلم **بالإنصات** إليه قبل أي إجراء؛ ليشعر بأن المدرسة تأخذ الأمر بجدية.","الطالب الخجول يبدأ معه المعلم ببناء **علاقة ثقة**، ثم يكلفه بمهام سهلة ينجح فيها. ومن الخطأ تجنب سؤاله أو تحويله فوراً إلى الموجه.","إذا أنجز الطالب ثم أساء، فصل المعلم **الاعتراف بالإنجاز** عن رفض السلوك، كأن يقول: «حلك صحيح، وضرب زميلك خطأ له عاقبة».","**العقاب الجماعي** ممنوع دائماً؛ لأنه يعاقب البريء مع المخطئ. ومثله في المنع العقاب البدني، والتشهير، والطرد من الفصل.","**التدخين** ولو خارج السور، في الشوارع المحاذية للمدرسة، يُبلِّغ عنه المعلم الموجه الطلابي والإدارة؛ إذ لا يُسقط وقوعه خارج السور مسؤولية المدرسة.","**جاهزية مصادر التعلم** أن تكون الأدوات صالحة ومتاحة للجميع؛ ولذلك يفحص المعلم الأجهزة والروابط قبل الحصة، ويجهز خطة بديلة.","**الإخلاء** عند الإنذار: هدوء، ثم خروج منتظم **دون الحقائب**، ثم العد في نقطة التجمع؛ لأن كل تأخير يزيد الخطر.","السلامة تبدأ **بإيقاف الخطر فوراً**، ثم حماية الطلاب، ثم الإسعاف في حدود التدريب، ثم الإبلاغ والتوثيق. ومعنى «في حدود التدريب» ألا يقدم المعلم إسعافاً لم يتدرب عليه.","تقوم السلامة في **المختبر** على إشراف دائم، ووسائل وقاية كالنظارات والقفازات.","عند محاولة طالب إيذاء ذاته (المادة 30) يلتزم المعلم الهدوء، ويأخذ كلامه بجدية، ويضعه في مكان آمن مع **عدم تركه بمفرده**، ثم يبلّغ فوراً.","يعرف المعلم **الحالات الصحية** لطلابه بالتنسيق مع الموجه الصحي؛ ليكون مستعداً إذا ظهرت أعراضها أثناء الحصة."],"m":[7]},{"h":"ثقافة التواصل","pts":["عناصر الاتصال خمسة: مرسل، ورسالة، وقناة، ومستقبل، و**تغذية راجعة**؛ وهي التي تجعل الاتصال في اتجاهين.","أفضل أنماط الاتصال الصفي **المتعدد** (المفتوح)، وفيه يتفاعل الجميع بتوجيه المعلم: المعلم مع الطلاب، والطلاب فيما بينهم.","التواصل **غير اللفظي** كالنظرة والإيماءة يسبق اللفظي أثراً؛ ولهذا يناسب التنبيه الصامت دون إحراج.","اللغة **التقاربية** توظيف المسافة من الطالب، كالاقتراب من مقعد الشارد دون كلام، أما اللغة **الموازية** فنبرة الصوت وسرعته.","**زمن الانتظار** بعد السؤال من 3 إلى 5 ثوانٍ، وهو يرفع جودة الإجابات؛ لأنه يمنح الطالب وقتاً للتفكير.","**الإنصات النشط** إيماء وإعادة صياغة لكلام الطالب دون مقاطعة؛ إذ تؤكد له إعادة الصياغة أنه فُهم.","التغذية الراجعة **تراكم معرفي** يخبر الطالب بما أصاب فيه وما يحتاج إلى تحسين، في حين أن التعزيز تراكم وجداني.","من وظائف التغذية الراجعة **التعزيزية**، وهي إخبار المتعلم بصحة استجابته لتثبيتها وتقوية ثقته بنفسه، و**الإخبارية**، وهي بيان الصواب والخطأ له ليصحح إجابته.","التغذية الراجعة الفاعلة فورية مستمرة لا متقطعة، وأقواها التعليق الفردي المحدد على الجوانب المميزة، لا ملصق «أحسنت» العام.","من أساليب التغذية الراجعة «نجمتان وأمنية»، أي نقطتا قوة ونقطة تحسين واحدة.","نظام **فلاندرز** يحلل التفاعل اللفظي في الصف؛ فالمدح، وتقبّل المشاعر والأفكار، وطرح الأسئلة كلام **غير مباشر**، أما الشرح والأوامر والنقد فكلام **مباشر**.","كثرة الكلام غير المباشر توسّع مشاركة الطلاب؛ لأن المعلم حين يتقبل أفكارهم ويسألهم يفتح لهم مجال الكلام."]},{"h":"قواعد اختيار البديل","pts":["**الخطوة الأولى** تعالج الموقف الحاضر مباشرة. أما الإجراء العام والوقائي والتبليغ فبدائل صحيحة في توقيت خاطئ؛ لأنها خطوات لاحقة.","عالج **السلوك لا الشخص**، على انفراد لا علناً؛ حتى لا يتحول التصحيح إلى إهانة للطالب أمام زملائه.","كل بديل فيه إهانة للطالب أو طرد من الفصل خاطئ، ولو بدا حازماً؛ ذلك أن الحزم المطلوب تطبيق القواعد بهدوء وعدل.","إذا جاء **بديلان مترادفان** فكلاهما خطأ؛ لأن للسؤال إجابة صحيحة واحدة، فلا يصح بديلان يحملان المعنى نفسه.","البيئة الإيجابية تبدأ **بالعلاقة** قبل الأدوات والعقوبات، كمناداة الطلاب بأسمائهم؛ إذ يتقبل الطالب قواعد معلم يعرفه ويهتم به.","مع **ولي الأمر الغاضب** يكون الترتيب: استمع ثم افهم ثم اشرح ثم اتفق. ولا يبدأ المعلم بوجهة نظره ولا بالقوانين؛ لأن ذلك يُشعره بأن شكواه لم تُسمع."]}]},"L15":{"sec":[{"h":"المفاهيم والاختبارات","pts":["**القياس** رقم بلا حكم، والتقييم حكم على قيمة الأداء، أما **التقويم** فهو الأشمل؛ لأنه حكم يتبعه علاج.","الاختبار **التحصيلي** يقيس ما تعلمه الطالب فعلاً، بخلاف اختبار الاستعداد الذي يتنبأ بنجاحه مستقبلاً.","الاختبار **المقنن** يعده متخصصون بتعليمات وظروف موحدة. أما اختبار المعلم فليس مقنناً، لكنه الأنسب لقياس تمكن طلابه مما درسوه في فترة محددة.","من صفات التقويم الجيد أنه علمي (صادق وثابت وموضوعي).","من مواصفات الاختبار الجيد **التمييز**، والشمول لمحتوى المادة وأهدافها."],"m":[0]},{"h":"أنواع التقويم ودوراته","pts":["**أنواع التقويم** بحسب زمنه: القبلي، والتكويني، والختامي، ثم التتبعي بعده بفترة لقياس بقاء الأثر.","التقويم التشخيصي يحدد نقاط القوة والضعف وأسباب الصعوبة؛ ولذلك يُشخَّص الخطأ المتكرر قبل علاجه.","التقويم **التكويني (البنائي)** يجري أثناء التدريس لتعديله بلا حكم نهائي، أما الختامي (التجميعي) ففي النهاية للحكم. ومن ثَمّ إذا ذكر السؤال «أثناء» و«تغذية راجعة» فجوابه التكويني.","التقويم **محكي المرجع** يقارن الطالب بمحك إتقان، ومعياري المرجع بأقرانه، وذاتي المرجع بأدائه السابق. ولذلك تدل كلمة «زملائه» أو «ترتيبه» على المعياري.","**تقويم التعلم** ختامي للحكم، والتقويم من أجل التعلم تكويني يقدّم أدلة توجّه الخطوة التالية، أما التقويم كتعلم فيراقب فيه الطالب تعلمه بنفسه.","التقويم **الرسمي** موثق بدرجة ويُبنى عليه حكم، بينما يجري غير الرسمي تلقائياً أثناء التدريس، كالملاحظة وبطاقة الخروج.","دورة التقويم قصيرة المدى داخل الحصة، أما طويلة المدى فعلى مستوى الوحدة والفترة والعام."]},{"h":"التقويم البديل وأدواته","pts":["التقويم **البديل** أو الأصيل يقيس الأداء في **مهام حقيقية**، بمعايير معلنة مسبقاً.","**قائمة الشطب (الرصد)** تسأل: موجود أم لا؟ وسلم التقدير العددي يسأل: بأي درجة؟ أما **الروبرك** (سلم التقدير الوصفي) فيصف كيف يبدو كل مستوى.","**ملف الإنجاز** (البورتفوليو) جمع منظم لأعمال مؤرخة خلال الفصل، هدفه **التأمل الذاتي** ومتابعة التقدم، لا الأرشفة.","يعتمد التقويم الذاتي وتقويم **الأقران** على محكات معلنة مسبقاً. كما يقوم تقويم الأقران على نشاطين: ملاحظة عمل الزميل، والتواصل معه بتغذية راجعة.","المهارة العملية كالوضوء تُقوَّم **بالملاحظة**؛ لأن الاختبار الكتابي يقيس المعرفة لا المهارة. أما الميول فتُقاس بالتقارير الذاتية.","**السجل القصصي** وصف سردي يكتبه المعلم، في حين يكتب الطالب نفسه سجل سير التعلم."]},{"h":"الأسئلة وبناء الاختبار","pts":["الأسئلة **الموضوعية** لا تقيس التعبير، وهي عرضة للتخمين؛ ولذلك **تُزاد** فيها البدائل الفعالة لتقليله.","الأسئلة **المقالية** تقيس التفكير والتعبير ولا مجال فيها للتخمين، لكن تصحيحها ذاتي فيقل ثباتها.","أسئلة الإجابة القصيرة والمقالية المقيدة **ليست موضوعية**؛ إذ يكتب الطالب إجابتها بأسلوبه، مع أن المقيدة تحدد نطاق الإجابة فترتفع موضوعية تصحيحها. أما الإكمال فموضوعي.","تُتجنَّب **كلمات الجزم** مثل «جميع» و«دائماً» في عبارات الصواب والخطأ؛ لأنها تكشف الإجابة لمن لم يتعلم.","تكون بدائل الاختيار من متعدد **متجانسة** ومعقولة ومتقاربة الطول؛ حتى لا يكشف طول أحدها الإجابة.","تُرتَّب فقرات الاختبار **من السهل إلى الصعب**؛ ليستمر متدني التحصيل في الإجابة ويقل قلقه.","يبدأ بناء الاختبار **بتحديد الأهداف**، ثم تحليل المحتوى، ثم جدول المواصفات، لا بكتابة الأسئلة.","**جدول المواصفات** مخطط ثنائي البعد يقاطع المحتوى مع مستويات الأهداف، فيحقق صدق المحتوى لا الثبات. ولذلك يعالج تركّز الأسئلة في درس واحد.","**الوزن** = حصص الموضوع أو أهدافه ÷ المجموع × 100. فوحدة لها 6 حصص من 20 نصيبها 12 سؤالاً من 40.","يكون التصحيح **بمعيار واحد للجميع** وبنموذج إجابة معدّ مسبقاً، لا بانطباع المصحح. أما ظرف الطالب فيُعالَج تربوياً، لا برفع درجته."],"m":[4]},{"h":"التسهيلات وذوو الإعاقة","pts":["**التسهيلات** تغيّر طريقة الاختبار أو مكانه أو زمنه **دون خفض** المستوى المقيس؛ ومن ثَمّ تُعدّ حقاً للطالب لا تفضيلاً.","من التسهيلات ألا يُختبر الطالب في أكثر من **مادة تحريرية** في اليوم الواحد، وبرايل للإعاقة البصرية.","أما **التعديل** فيغيّر محتوى التقويم نفسه، كأن يُقوَّم من لم يستفد من الفصل العام في محتوى **خطته الفردية**.","يشرف معلم **التربية الخاصة** على تقويم الطالب ذي الإعاقة، بالتعاون مع معلم التعليم العام."],"m":[6]},{"h":"اللائحة والاختبارات الدولية","pts":["يُقوَّم **الصفان الأول والثاني الابتدائي** بمستويات أداء في معظم المواد، ويكون النجاح فيهما بإتقان **75%** من معايير المادة بما فيها معايير الحد الأدنى.","من **الثالث الابتدائي** توزَّع درجة المادة: **60 درجة** للتقويمات التكوينية، و**40 درجة** لاختبار نهاية الفترة.","يُشترط للنجاح من الثالث الابتدائي تحقيق **النهاية الصغرى 50%** و**النسبة الشرطية 20%** من درجة الاختبار التحريري، ولا تُطبَّق الشرطية في الدور الثاني.","**نافس** اختبارات وطنية للصفوف 3 و 6 و 9، تشخّص المستوى الوطني لتحسين التعليم لا لنجاح الطالب.","اختبار **PISA** من منظمة OECD لعمر 15 سنة كل 3 سنوات (وكل 4 بعد دورة 2025).","اختبار TIMSS للصفين الرابع والثامن كل 4 سنوات، في حين يقيس PIRLS قراءة الصف الرابع كل 5 سنوات.","أما TALIS فمسح دولي عن المعلمين، لا اختبار للطلاب."]}]},"L16":{"sec":[{"h":"الصدق","pts":["**الصدق** أن يقيس الاختبار ما وُضع لقياسه، لغرض محدد وفئة معينة؛ فقد يصدق في غرض دون غيره.","**صدق المحتوى** أن تمثّل الأسئلة المحتوى وأهدافه تمثيلاً متوازناً، ويُتحقق منه بجدول المواصفات وتحكيم المختصين.","**صدق البناء** يُتحقق منه بالتحليل العاملي، أما **الصدق الظاهري** فمجرد مظهر، وهو أضعف أنواع الصدق.","**صدق المحك** يُقدَّر **بمعامل ارتباط** مع محك خارجي، أي مقياس مستقل لما يُفترض أن يقيسه الاختبار أو يتنبأ به.","يُجمع محك **التلازمي** في الوقت نفسه، ومحك **التنبؤي** في المستقبل؛ ومن ثَمّ تدل «بعد سنة» أو «سينجح» على التنبؤي.","**الصدق الذاتي** الجذر التربيعي لمعامل الثبات، وهو الحد الأعلى للصدق؛ فثبات 0.81 يعطي صدقاً ذاتياً 0.9."],"m":[0]},{"h":"الثبات والموضوعية","pts":["**الثبات** اتساق النتائج عند تكرار القياس، ومعامله بين 0 و 1؛ وكلما اقترب من 1 زاد الاتساق.","الثبات شرط **ضروري غير كافٍ** للصدق؛ إذ إن الصادق ثابت بالضرورة، أما الثابت فقد لا يكون صادقاً، كميزان يزيد كيلوين دائماً.","تتميز طرق الثبات بعدد الاختبارات ومرات التطبيق: إعادة التطبيق اختبار واحد مرتين، والصور المتكافئة اختباران، و**التجزئة النصفية** اختبار واحد مرة واحدة، يُصحَّح معامله بسبيرمان براون.","للاتساق الداخلي معاملان: كودر ريتشاردسون للفقرات الثنائية (صح أو خطأ)، وكرونباخ ألفا للمقاييس المتدرجة كمقياس ليكرت. وكلاهما يقيس الثبات لا الصدق.","**الخطأ المعياري للقياس** = الانحراف المعياري × √(1 − الثبات)، وعلاقته بالثبات عكسية؛ فكلما كبر الخطأ قلّ الثبات.","بانحراف 10 وثبات 0.84 يكون الخطأ 10 × 0.4 = 4. وعليه فمن نال 70 تقع درجته الحقيقية غالباً **من 66 إلى 74**.","**عوامل الثبات**: يرفعه طول الاختبار وتباين العينة، في حين يخفضه التخمين والعينة شديدة التجانس؛ إذ تقل الصدفة بكثرة الفقرات وتزيد بالتخمين.","**الموضوعية** استقلال الدرجة عن ذاتية المصحح، وهي شرط للثبات؛ لأن اختلاف المصححين في الإجابة نفسها يغيّر درجة الطالب."],"m":[1]},{"h":"تحليل الفقرات","pts":["**معامل الصعوبة** (السهولة) = عدد المصيبين ÷ عدد المجيبين؛ ولذلك كلما ارتفع كانت الفقرة **أسهل**. مثال ذلك 14 مصيباً من 25 طالباً، فالمعامل 0.56.","المدى الشائع لمعامل الصعوبة من 0.20 إلى 0.80، أما دليل الاختبارات 2025 فيوصي بالإبقاء على الفقرة بين 30% و 70%.","لا يُحسب معامل الصعوبة **بالمخطئين** إلا إذا نص السؤال عليهم؛ لأن الاختبار يقصد غالباً المصيبين. ومن يحسب بهم في المثال يكتب 0.44.","**معامل الصعوبة في السؤال المقالي** = مجموع درجاته ÷ (عدد الطلاب × درجته). فسؤال من 5 درجات لعشرين طالباً مجموع درجاتهم 60 معامله 0.60.","**معامل التمييز** = (صحيح العليا − صحيح الدنيا) ÷ عدد إحدى الفئتين، وتؤخذ 27% من كل طرف.","تفسير التمييز: الممتاز من 0.40، والجيد من 0.30، ومن 0.20 إلى 0.29 تُعدَّل الفقرة. وما دون 0.20 ضعيف تُحذف فقرته، وكذلك **السالب**.","**المشتت الفعال** تختاره الفئة الدنيا أكثر من العليا؛ لأن وظيفته أن يجذب من لم يتقن المحتوى دون أن يخدع المتقنين.","المشتت الذي لا يختاره أحد يُستبدل بمشتت معقول، إذ يقلل عدد البدائل الحقيقية أمام الطالب فيسهل عليه التخمين."]},{"h":"مستويات القياس","pts":["مستويات القياس عند **ستيفنز** أربعة، يزيد كل منها على ما قبله خاصية: التصنيف، ثم الترتيب، ثم تساوي المسافات، ثم الصفر الحقيقي.","**الاسمي** يصنف ويسمي فقط كأرقام اللاعبين، في حين يرتب **الرتبي** بلا مسافات متساوية، كالأول والثاني والثالث؛ فلا يبين مقدار الفرق بينهم.","**الفتري** مسافاته متساوية وصفره اعتباري، كدرجات الاختبار والحرارة المئوية؛ ولذلك لا يُقال إن 40 ضعف 20. أما **النسبي** فصفره حقيقي كالطول والوزن، ويصح فيه قول «ضعف» و«نصف»."]},{"h":"الإحصاء الوصفي","pts":["**المتوسط** يتأثر بالقيم المتطرفة: الدرجات 4، 6، 6، 7، 9، 10، 14 متوسطها 8، ولو صارت 14 هي 49 لقفز المتوسط إلى 13.","**الوسيط** القيمة الوسطى بعد الترتيب، وفي العدد الزوجي متوسط العددين الأوسطين. ولا يتأثر بالقيم المتطرفة، ولذلك يناسب البيانات الملتوية.","**المنوال** القيمة الأكثر تكراراً، ويناسب البيانات النوعية كالجنس؛ لأنها لا تُجمع ولا تُرتب، فلا يُحسب لها متوسط ولا وسيط.","**المدى** أكبر قيمة ناقص أصغرها، وتغيّره درجة متطرفة واحدة. أما **الانحراف المعياري** فجذر التباين، وكلما صغر كان الصف أكثر تجانساً.","إضافة ثابت إلى كل الدرجات تغيّر المتوسط بقدر الثابت ولا تغيّر الانحراف المعياري؛ لأن المسافات بينها تبقى كما هي.","**المدرج التكراري** لعرض توزيع الدرجات، أما القطاع الدائري فللنسب، والخط البياني للتغير عبر الزمن.","**معامل الارتباط** من سالب 1 إلى موجب 1، إشارته اتجاه وقيمته قوة: أقل من 0.3 ضعيف، وفوق 0.7 قوي. فسالب 0.8 أقوى من موجب 0.5.","الارتباط لا يثبت السببية مهما كانت قوته، إذ قد يرجع اقتران المتغيرين إلى عامل ثالث يؤثر فيهما."]},{"h":"المنحنى والدرجات المعيارية","pts":["**التوزيع الاعتدالي** متماثل يتساوى فيه المتوسط والوسيط والمنوال، وفيه نحو 68% من الدرجات ضمن ± انحراف، و 95% ضمن انحرافين، و 99.7% ضمن ثلاثة.","إذا كانت الأغلبية منخفضة والقلة عالية، فالاختبار **صعب** والتوزيع ذو **الالتواء الموجب**. والمتوسط فيه أكبر من الوسيط؛ لأن القلة العالية ترفعه.","أما إذا كانت الأغلبية مرتفعة والقلة منخفضة، فالاختبار سهل والالتواء **سالب**. والقاعدة أن الإشارة تتبع ذيل القلة، لا موضع التكدس.","**التفرطح** يصف القمة مقارنة بالمنحنى الاعتدالي: المدبب قمته أحدّ منه، والمفرطح أكثر انبساطاً؛ بينما يصف الالتواء ميل التوزيع إلى أحد الجانبين.","**الدرجة المعيارية ز** = (الدرجة − المتوسط) ÷ الانحراف، ومتوسطها 0 وانحرافها 1. ولذلك تصلح للمقارنة بين مادتين مختلفتين.","الدرجة **ت** = 50 + 10 × ز، فمتوسطها 50 وانحرافها 10؛ مثال ذلك أن ز = 2 تقابلها ت = 70.","**الرتبة المئينية** 90 تعني التفوق على 90% من المجموعة، لا الإجابة الصحيحة عن 90% من الأسئلة؛ لأنها موقع الطالب بين أقرانه."],"m":[5]},{"h":"الرصد وتوظيف النتائج","pts":["يرصد المعلم أداء طلابه في **نماذج رصد** تراكمية: صف لكل طالب، وأعمدة للمعايير والأداة والتاريخ والإجراء العلاجي.","في الصفين الأول والثاني يدوّن المعلم التقويم يومياً في سجل المتابعة، ثم يرصد الخلاصة في النظام الرقمي نهاية الفترة.","**نسبة الإتقان لكل معيار** = عدد المتقنين ÷ عدد الطلاب. ويلوّن المعلم غير المتقنين في برنامج الجداول بالتنسيق الشرطي، لتظهر مواطن الضعف بسرعة.","المعيار الضعيف لدى **أغلب الصف** يُعاد تدريسه للجميع؛ لأن ضعف الأغلبية يدل على حاجة التدريس نفسه إلى تعديل. أما ضعف **القلة** فتعالجه خطة علاجية فردية أو في مجموعة صغيرة.","**سرية البيانات**: نتيجة الطالب تخصه وتخص ولي أمره والقائمين على تعليمه فقط، كما تنص لائحة تقويم الطالب 2025؛ ولذلك لا تُنشر النتائج.","**التغذية الراجعة** الفعالة **فورية** ينتفع بها الطالب ما دام يتذكر أخطاءه، ووصفية تتناول المهمة لا الشخص. ومن ثَمّ يضعفها التأخير أو الثناء العام.","التغذية الراجعة التي تبين للطالب ما أصاب فيه وما أخطأ، وتوجهه إلى خطوته التالية، **تكوينية**؛ لأنها تقود إلى تحسين لاحق.","بعد التحليل يُبنى برنامج **علاجي** لمن أخفق في مهارة محددة، وبرنامج **إثرائي** للمتفوقين؛ ليأخذ كل منهم ما يحتاجه.","تقرير ولي الأمر يصف **مستوى ابنه** وتقدمه وحاجاته، دون مقارنته بغيره؛ إذ غايته الشراكة مع الأسرة في دعم تعلمه.","إذا تدنّت نتائج الصف كله، فالخطوة الأولى **تحليل النتائج** ثم تعديل التدريس، لا إعادة الاختبار بأسئلة أسهل؛ لأن التحليل يكشف موضع الخلل."]}]}};
window.__dataDone&&window.__dataDone("quick");